const g={"ko-first-u01.title":"动物","ko-first-u01.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u01.w.0":"猫","ko-first-u01.w.1":"小狗","ko-first-u01.w.2":"鱼","ko-first-u01.w.3":"鸟","ko-first-u01.w.4":"牛","ko-first-u01.w.5":"猪","ko-first-u02.title":"吃的东西","ko-first-u02.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u02.w.0":"苹果","ko-first-u02.w.1":"香蕉","ko-first-u02.w.2":"牛奶","ko-first-u02.w.3":"面包","ko-first-u02.w.4":"鸡蛋","ko-first-u02.w.5":"米饭","ko-first-u03.title":"玩具","ko-first-u03.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u03.w.0":"球","ko-first-u03.w.1":"汽车","ko-first-u03.w.2":"玩具熊","ko-first-u03.w.3":"风筝","ko-first-u03.w.4":"火车","ko-first-u03.w.5":"船","ko-first-u04.title":"身体","ko-first-u04.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u04.w.0":"眼睛","ko-first-u04.w.1":"耳朵","ko-first-u04.w.2":"鼻子","ko-first-u04.w.3":"嘴巴","ko-first-u04.w.4":"手","ko-first-u04.w.5":"脚","ko-first-u05.title":"颜色","ko-first-u05.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u05.w.0":"红色","ko-first-u05.w.1":"蓝色","ko-first-u05.w.2":"黄色","ko-first-u05.w.3":"绿色","ko-first-u05.w.4":"黑色","ko-first-u05.w.5":"白色","ko-first-u06.title":"家人","ko-first-u06.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u06.w.0":"妈妈","ko-first-u06.w.1":"爸爸","ko-first-u06.w.2":"宝宝","ko-first-u06.w.3":"奶奶","ko-first-u06.w.4":"爷爷","ko-first-u06.w.5":"孩子","ko-first-u07.title":"在家里","ko-first-u07.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u07.w.0":"房子","ko-first-u07.w.1":"床","ko-first-u07.w.2":"椅子","ko-first-u07.w.3":"门","ko-first-u07.w.4":"书","ko-first-u07.w.5":"杯子","ko-first-u08.title":"在外面","ko-first-u08.tip":"看看图，听一听，一起用韩语说出来。孩子还不认字也没关系。","ko-first-u08.w.0":"太阳","ko-first-u08.w.1":"月亮","ko-first-u08.w.2":"星星","ko-first-u08.w.3":"树","ko-first-u08.w.4":"花","ko-first-u08.w.5":"雨"},k={"ko-kinder-u01.title":"元音 ㅏ ㅓ ㅗ ㅜ ㅣ","ko-kinder-u01.tip":"韩语的字母会拼成一个个方块字。开头的 ㅇ 不发音，所以 아 就读作“a”。张大嘴巴说说看：아、어、오、우、이！","ko-kinder-u01.w.0":"宝宝","ko-kinder-u01.w.1":"冰淇淋","ko-kinder-u01.w.2":"妈妈","ko-kinder-u01.w.3":"鸭子","ko-kinder-u01.w.4":"黄瓜","ko-kinder-u01.w.5":"牛奶","ko-kinder-u01.w.6":"雨伞","ko-kinder-u01.w.7":"牙齿","ko-kinder-u01.s.0":"宝宝在睡觉。","ko-kinder-u01.s.1":"鸭子来了。","ko-kinder-u01.s.2":"请给我牛奶。","ko-kinder-u02.title":"字母 ㄱ ㄴ ㄷ","ko-kinder-u02.tip":"一个方块字由辅音加元音组成：ㄱ + ㅏ = 가。点一点字母卡片听听它的名字，再一起读出方块字。","ko-kinder-u02.w.0":"书包","ko-kinder-u02.w.1":"肉","ko-kinder-u02.w.2":"鞋子","ko-kinder-u02.w.3":"蝴蝶","ko-kinder-u02.w.4":"树","ko-kinder-u02.w.5":"歌","ko-kinder-u02.w.6":"松鼠","ko-kinder-u02.w.7":"橡子","ko-kinder-u02.s.0":"蝴蝶在飞。","ko-kinder-u02.s.1":"书包很大。","ko-kinder-u02.s.2":"松鼠在吃东西。","ko-kinder-u03.title":"字母 ㄹ ㅁ ㅂ","ko-kinder-u03.tip":"ㄹ 的发音介于“r”和“l”之间。ㅁ 长得像闭上的嘴巴——读它的时候也要闭上嘴唇哦！","ko-kinder-u03.w.0":"拉面","ko-kinder-u03.w.1":"柠檬","ko-kinder-u03.w.2":"马","ko-kinder-u03.w.3":"帽子","ko-kinder-u03.w.4":"彩虹","ko-kinder-u03.w.5":"香蕉","ko-kinder-u03.w.6":"公交车","ko-kinder-u03.w.7":"雨","ko-kinder-u03.s.0":"帽子很漂亮。","ko-kinder-u03.s.1":"公交车来了。","ko-kinder-u03.s.2":"在下雨。","ko-kinder-u04.title":"字母 ㅅ ㅇ ㅈ","ko-kinder-u04.tip":"ㅇ 在方块字开头时不发音（아、오），放在下面就读作“ng”（방）。ㅅ 像一顶小帐篷：사、소。","ko-kinder-u04.w.0":"狮子","ko-kinder-u04.w.1":"苹果","ko-kinder-u04.w.2":"牛","ko-kinder-u04.w.3":"西瓜","ko-kinder-u04.w.4":"时钟","ko-kinder-u04.w.5":"汽车","ko-kinder-u04.w.6":"果汁","ko-kinder-u04.w.7":"地球","ko-kinder-u04.s.0":"狮子很大。","ko-kinder-u04.s.1":"请给我果汁。","ko-kinder-u04.s.2":"西瓜很好吃。","ko-kinder-u05.title":"字母 ㅊ ㅋ ㅌ","ko-kinder-u05.tip":"ㅊ、ㅋ、ㅌ 是“送气”的字母：ㅋ 就是 ㄱ 多一笔，也多送一口气。把手放在嘴巴前面感觉一下！","ko-kinder-u05.w.0":"裙子","ko-kinder-u05.w.1":"奶酪","ko-kinder-u05.w.2":"鼻子","ko-kinder-u05.w.3":"大象","ko-kinder-u05.w.4":"饼干","ko-kinder-u05.w.5":"兔子","ko-kinder-u05.w.6":"西红柿","ko-kinder-u05.w.7":"卡车","ko-kinder-u05.s.0":"兔子在蹦蹦跳跳。","ko-kinder-u05.s.1":"大象的鼻子很长。","ko-kinder-u05.s.2":"请给我饼干。","ko-kinder-u06.title":"字母 ㅍ ㅎ","ko-kinder-u06.tip":"ㅎ 读作“h”——하、호、후，就像小小的笑声。现在你认识全部 14 个基本辅音啦！","ko-kinder-u06.w.0":"葡萄","ko-kinder-u06.w.1":"披萨","ko-kinder-u06.w.2":"波浪","ko-kinder-u06.w.3":"企鹅","ko-kinder-u06.w.4":"河马","ko-kinder-u06.w.5":"太阳","ko-kinder-u06.w.6":"老虎","ko-kinder-u06.w.7":"纸巾","ko-kinder-u06.s.0":"企鹅在走路。","ko-kinder-u06.s.1":"老虎在睡觉。","ko-kinder-u06.s.2":"葡萄很好吃。","ko-kinder-u07.title":"元音 ㅑ ㅕ ㅛ ㅠ ㅐ ㅔ","ko-kinder-u07.tip":"多加一笔就多了“y”的音：ㅏ (a) → ㅑ (ya)，ㅗ (o) → ㅛ (yo)。ㅐ 和 ㅔ 现在的读音几乎一样——连韩国人也常常搞混！","ko-kinder-u07.w.0":"棒球","ko-kinder-u07.w.1":"狐狸","ko-kinder-u07.w.2":"做饭","ko-kinder-u07.w.3":"鬼","ko-kinder-u07.w.4":"毛毛虫","ko-kinder-u07.w.5":"狗","ko-kinder-u07.w.6":"梨","ko-kinder-u07.w.7":"螃蟹","ko-kinder-u07.s.0":"狐狸在笑。","ko-kinder-u07.s.1":"螃蟹在走路。","ko-kinder-u07.s.2":"我在做饭。","ko-kinder-u08.title":"底下的字母（收音）","ko-kinder-u08.tip":"辅音也可以放在方块字的最下面：ㄱ + ㅗ + ㅁ = 곰。这个底下的字母叫作收音（받침）。现在你几乎能读出所有韩语单词了！","ko-kinder-u08.w.0":"熊","ko-kinder-u08.w.1":"球","ko-kinder-u08.w.2":"雪","ko-kinder-u08.w.3":"山","ko-kinder-u08.w.4":"面包","ko-kinder-u08.w.5":"星星","ko-kinder-u08.w.6":"月亮","ko-kinder-u08.w.7":"水","ko-kinder-u08.s.0":"熊在睡觉。","ko-kinder-u08.s.1":"在下雪。","ko-kinder-u08.s.2":"请给我水。"},o={"ko-g12-u01.title":"打招呼","ko-g12-u01.tip":"说 안녕하세요 的时候要微微鞠躬——这就是韩国人打招呼的方式。跟好朋友只说 안녕! 就可以啦！","ko-g12-u01.w.0":"你好","ko-g12-u01.w.1":"再见（对离开的人说）","ko-g12-u01.w.2":"谢谢","ko-g12-u01.w.3":"对不起","ko-g12-u01.w.4":"是","ko-g12-u01.w.5":"不是","ko-g12-u01.w.6":"朋友","ko-g12-u01.w.7":"老师","ko-g12-u01.w.8":"晚安","ko-g12-u01.s.0":"老师好。","ko-g12-u01.s.1":"好的，谢谢。","ko-g12-u01.s.2":"不用了，没关系。","ko-g12-u01.s.3":"真的很对不起。","ko-g12-u01.s.4":"嗨，朋友！","ko-g12-u01.s.5":"妈妈，晚安。","ko-g12-u02.title":"数字 1–10","ko-g12-u02.tip":"韩语有两套数字。하나, 둘, 셋 用来数东西和说年龄。用它们数数手指吧！","ko-g12-u02.w.0":"一","ko-g12-u02.w.1":"二","ko-g12-u02.w.2":"三","ko-g12-u02.w.3":"四","ko-g12-u02.w.4":"五","ko-g12-u02.w.5":"六","ko-g12-u02.w.6":"七","ko-g12-u02.w.7":"八","ko-g12-u02.w.8":"九","ko-g12-u02.w.9":"十","ko-g12-u02.s.0":"一、二、三！","ko-g12-u02.s.1":"四、五、六。","ko-g12-u02.s.2":"七、八、九、十。","ko-g12-u02.s.3":"我五岁了。","ko-g12-u02.s.4":"我有十根手指。","ko-g12-u02.s.5":"请再给我一个。","ko-g12-u03.title":"颜色","ko-g12-u03.tip":"所有颜色词都以 색（颜色）结尾。指着身边的东西说出它的颜色：빨간색！","ko-g12-u03.w.0":"红色","ko-g12-u03.w.1":"蓝色","ko-g12-u03.w.2":"黄色","ko-g12-u03.w.3":"绿色","ko-g12-u03.w.4":"紫色","ko-g12-u03.w.5":"橙色","ko-g12-u03.w.6":"粉红色","ko-g12-u03.w.7":"黑色","ko-g12-u03.w.8":"白色","ko-g12-u03.s.0":"苹果是红色的。","ko-g12-u03.s.1":"天空是蓝色的。","ko-g12-u03.s.2":"香蕉是黄色的。","ko-g12-u03.s.3":"叶子是绿色的。","ko-g12-u03.s.4":"葡萄是紫色的。","ko-g12-u03.s.5":"我喜欢粉红色。","ko-g12-u04.title":"家人","ko-g12-u04.tip":"韩国人说到家人和家时，会用 우리（我们的）代替“我的”：우리 엄마, 우리 집。听起来温暖又亲切。","ko-g12-u04.w.0":"家庭","ko-g12-u04.w.1":"妈妈","ko-g12-u04.w.2":"爸爸","ko-g12-u04.w.3":"奶奶","ko-g12-u04.w.4":"爷爷","ko-g12-u04.w.5":"弟弟或妹妹","ko-g12-u04.w.6":"宝宝","ko-g12-u04.w.7":"小狗","ko-g12-u04.s.0":"这是我的家人。","ko-g12-u04.s.1":"妈妈，我爱你。","ko-g12-u04.s.2":"爸爸个子很高。","ko-g12-u04.s.3":"奶奶在笑。","ko-g12-u04.s.4":"弟弟（妹妹）在哭。","ko-g12-u04.s.5":"小狗也是家人。","ko-g12-u05.title":"动物","ko-g12-u05.tip":"韩语里的动物叫声很好玩：猫叫 야옹，狗叫 멍멍，青蛙叫 개굴개굴。学学看吧！","ko-g12-u05.w.0":"猫","ko-g12-u05.w.1":"猴子","ko-g12-u05.w.2":"长颈鹿","ko-g12-u05.w.3":"老鼠","ko-g12-u05.w.4":"蛇","ko-g12-u05.w.5":"鸡","ko-g12-u05.w.6":"羊","ko-g12-u05.w.7":"乌龟","ko-g12-u05.w.8":"青蛙","ko-g12-u05.s.0":"猫咪喵喵叫。","ko-g12-u05.s.1":"长颈鹿的脖子很长。","ko-g12-u05.s.2":"猴子在吃香蕉。","ko-g12-u05.s.3":"乌龟很慢。","ko-g12-u05.s.4":"青蛙跳来跳去。","ko-g12-u05.s.5":"羊在吃草。","ko-g12-u06.title":"水果","ko-g12-u06.tip":"배 是“梨”——也可以是“船”和“肚子”！看图就知道是哪一个。","ko-g12-u06.w.0":"苹果","ko-g12-u06.w.1":"香蕉","ko-g12-u06.w.2":"草莓","ko-g12-u06.w.3":"葡萄","ko-g12-u06.w.4":"西瓜","ko-g12-u06.w.5":"橘子","ko-g12-u06.w.6":"桃子","ko-g12-u06.w.7":"梨","ko-g12-u06.w.8":"猕猴桃","ko-g12-u06.s.0":"草莓是红色的。","ko-g12-u06.s.1":"橘子很甜。","ko-g12-u06.s.2":"我喜欢桃子。","ko-g12-u06.s.3":"西瓜真的很大。","ko-g12-u06.s.4":"请给我葡萄。","ko-g12-u06.s.5":"猕猴桃是绿色的。","ko-g12-u07.title":"食物","ko-g12-u07.tip":"韩国人吃饭前会说 잘 먹겠습니다（我要开动了），吃完后说 잘 먹었습니다。下次吃饭时试试看！","ko-g12-u07.w.0":"米饭","ko-g12-u07.w.1":"泡菜","ko-g12-u07.w.2":"汤","ko-g12-u07.w.3":"紫菜包饭","ko-g12-u07.w.4":"年糕","ko-g12-u07.w.5":"饺子","ko-g12-u07.w.6":"鸡蛋","ko-g12-u07.w.7":"鱼（吃的）","ko-g12-u07.w.8":"勺子","ko-g12-u07.w.9":"筷子","ko-g12-u07.s.0":"我吃饭。","ko-g12-u07.s.1":"泡菜很辣。","ko-g12-u07.s.2":"饺子很好吃。","ko-g12-u07.s.3":"汤很烫。","ko-g12-u07.s.4":"我用筷子吃。","ko-g12-u07.s.5":"请给我紫菜包饭。","ko-g12-u07.s.6":"我饿了。","ko-g12-u08.title":"身体","ko-g12-u08.tip":"用韩语玩“老师说”游戏：코! 귀! 머리! 听到哪个部位就摸哪里。","ko-g12-u08.w.0":"头","ko-g12-u08.w.1":"眼睛","ko-g12-u08.w.2":"鼻子","ko-g12-u08.w.3":"嘴巴","ko-g12-u08.w.4":"耳朵","ko-g12-u08.w.5":"手","ko-g12-u08.w.6":"脚","ko-g12-u08.w.7":"腿","ko-g12-u08.w.8":"手臂","ko-g12-u08.s.0":"我有两只眼睛。","ko-g12-u08.s.1":"摸摸你的鼻子。","ko-g12-u08.s.2":"我洗手。","ko-g12-u08.s.3":"把嘴巴张大。","ko-g12-u08.s.4":"我头痛。","ko-g12-u08.s.5":"我的腿很长。","ko-g12-u09.title":"学校","ko-g12-u09.tip":"在韩国，学生叫老师 선생님——从来不会直接叫名字。님 是表示尊敬的礼貌词尾。","ko-g12-u09.w.0":"学校","ko-g12-u09.w.1":"教室","ko-g12-u09.w.2":"铅笔","ko-g12-u09.w.3":"橡皮","ko-g12-u09.w.4":"本子","ko-g12-u09.w.5":"剪刀","ko-g12-u09.w.6":"书桌","ko-g12-u09.w.7":"黑板","ko-g12-u09.w.8":"作业","ko-g12-u09.s.0":"我去上学。","ko-g12-u09.s.1":"我有铅笔。","ko-g12-u09.s.2":"请借我橡皮。","ko-g12-u09.s.3":"我在本子上写字。","ko-g12-u09.s.4":"我有很多作业。","ko-g12-u09.s.5":"老师，我有问题！","ko-g12-u10.title":"在家里","ko-g12-u10.tip":"韩国人进屋前会在门口脱鞋。地板常常是暖暖的（地暖“温突”）——好舒服！","ko-g12-u10.w.0":"房子","ko-g12-u10.w.1":"房间","ko-g12-u10.w.2":"厨房","ko-g12-u10.w.3":"卫生间","ko-g12-u10.w.4":"灯","ko-g12-u10.w.5":"门","ko-g12-u10.w.6":"沙发","ko-g12-u10.w.7":"冰箱","ko-g12-u10.w.8":"电视","ko-g12-u10.s.0":"我们家很小。","ko-g12-u10.s.1":"这是我的房间。","ko-g12-u10.s.2":"妈妈在厨房。","ko-g12-u10.s.3":"我把灯打开。","ko-g12-u10.s.4":"我坐在沙发上。","ko-g12-u10.s.5":"卫生间在哪里？","ko-g12-u11.title":"衣服","ko-g12-u11.tip":"韩语的“穿戴”有不同的动词：衣服用 입어요，袜子和鞋子用 신어요，帽子用 써요。很有趣吧？","ko-g12-u11.w.0":"衣服","ko-g12-u11.w.1":"T恤","ko-g12-u11.w.2":"裤子","ko-g12-u11.w.3":"裙子","ko-g12-u11.w.4":"袜子","ko-g12-u11.w.5":"鞋子","ko-g12-u11.w.6":"帽子","ko-g12-u11.w.7":"手套","ko-g12-u11.w.8":"睡衣","ko-g12-u11.s.0":"我穿衣服。","ko-g12-u11.s.1":"我穿袜子。","ko-g12-u11.s.2":"我戴帽子。","ko-g12-u11.s.3":"鞋子太小了。","ko-g12-u11.s.4":"手套很暖和。","ko-g12-u11.s.5":"睡衣很漂亮。","ko-g12-u12.title":"天气","ko-g12-u12.tip":"韩语里雨和雪是“来”的：비가 와요, 눈이 와요。韩国四季分明——你喜欢哪个季节？","ko-g12-u12.w.0":"天气","ko-g12-u12.w.1":"太阳","ko-g12-u12.w.2":"雨","ko-g12-u12.w.3":"雪","ko-g12-u12.w.4":"风","ko-g12-u12.w.5":"云","ko-g12-u12.w.6":"春天","ko-g12-u12.w.7":"夏天","ko-g12-u12.w.8":"秋天","ko-g12-u12.w.9":"冬天","ko-g12-u12.s.0":"天气很好。","ko-g12-u12.s.1":"在下雨。","ko-g12-u12.s.2":"在下雪。","ko-g12-u12.s.3":"在刮风。","ko-g12-u12.s.4":"夏天很热。","ko-g12-u12.s.5":"冬天很冷。","ko-g12-u12.s.6":"春天花开了。","ko-g12-u13.title":"星期和时间","ko-g12-u13.tip":"星期几都以 요일（星期）结尾。토요일 和 일요일 是周末——太好了！","ko-g12-u13.w.0":"星期一","ko-g12-u13.w.1":"星期五","ko-g12-u13.w.2":"星期六","ko-g12-u13.w.3":"星期天","ko-g12-u13.w.4":"今天","ko-g12-u13.w.5":"明天","ko-g12-u13.w.6":"昨天","ko-g12-u13.w.7":"早上","ko-g12-u13.w.8":"晚上","ko-g12-u13.s.0":"今天是星期一。","ko-g12-u13.s.1":"明天是星期六。","ko-g12-u13.s.2":"我星期天休息。","ko-g12-u13.s.3":"我早上起床。","ko-g12-u13.s.4":"我晚上睡觉。","ko-g12-u13.s.5":"我喜欢星期五。","ko-g12-u14.title":"交通工具","ko-g12-u14.tip":"在韩语里，坐什么交通工具都用同一个动词“乘坐”：버스를 타요, 자전거를 타요, 비행기를 타요。","ko-g12-u14.w.0":"公交车","ko-g12-u14.w.1":"地铁","ko-g12-u14.w.2":"出租车","ko-g12-u14.w.3":"火车","ko-g12-u14.w.4":"飞机","ko-g12-u14.w.5":"自行车","ko-g12-u14.w.6":"船","ko-g12-u14.w.7":"汽车","ko-g12-u14.w.8":"马路","ko-g12-u14.s.0":"我坐公交车。","ko-g12-u14.s.1":"地铁很快。","ko-g12-u14.s.2":"我骑自行车。","ko-g12-u14.s.3":"飞机在飞。","ko-g12-u14.s.4":"火车很长。","ko-g12-u14.s.5":"路上堵车了。","ko-g12-u15.title":"玩具和游戏","ko-g12-u15.tip":"玩捉迷藏时，韩国小朋友会数完数喊：꼭꼭 숨어라, 머리카락 보일라——“藏好哦，头发都露出来啦！”","ko-g12-u15.w.0":"玩具","ko-g12-u15.w.1":"娃娃","ko-g12-u15.w.2":"积木","ko-g12-u15.w.3":"球","ko-g12-u15.w.4":"滑板车","ko-g12-u15.w.5":"拼图","ko-g12-u15.w.6":"气球","ko-g12-u15.w.7":"游戏","ko-g12-u15.w.8":"捉迷藏","ko-g12-u15.s.0":"一起玩吧！","ko-g12-u15.s.1":"我扔球。","ko-g12-u15.s.2":"我骑滑板车。","ko-g12-u15.s.3":"我用积木搭房子。","ko-g12-u15.s.4":"气球飞走了。","ko-g12-u15.s.5":"我们玩捉迷藏吧。","ko-g12-u16.title":"大自然","ko-g12-u16.tip":"韩国到处都是山，所以爬山（등산）是很受欢迎的家庭周末活动。","ko-g12-u16.w.0":"山","ko-g12-u16.w.1":"大海","ko-g12-u16.w.2":"河","ko-g12-u16.w.3":"天空","ko-g12-u16.w.4":"花","ko-g12-u16.w.5":"树","ko-g12-u16.w.6":"草","ko-g12-u16.w.7":"沙子","ko-g12-u16.w.8":"星星","ko-g12-u16.s.0":"山很高。","ko-g12-u16.s.1":"大海很宽广。","ko-g12-u16.s.2":"天空很晴朗。","ko-g12-u16.s.3":"花很漂亮。","ko-g12-u16.s.4":"树很大。","ko-g12-u16.s.5":"夜空中有很多星星。","ko-g12-u17.title":"心情","ko-g12-u17.tip":"韩语的心情词用起来像动词：기뻐요 本身就是“（我）很开心”。如果有人看起来很难过，就问一句 괜찮아요?","ko-g12-u17.w.0":"开心","ko-g12-u17.w.1":"难过","ko-g12-u17.w.2":"生气","ko-g12-u17.w.3":"害怕","ko-g12-u17.w.4":"累","ko-g12-u17.w.5":"兴奋","ko-g12-u17.w.6":"无聊","ko-g12-u17.w.7":"没事","ko-g12-u17.s.0":"我很开心。","ko-g12-u17.s.1":"我的朋友很难过。","ko-g12-u17.s.2":"我好累。","ko-g12-u17.s.3":"今天好兴奋！","ko-g12-u17.s.4":"你真的没事吗？","ko-g12-u17.s.5":"嗯，我没事。","ko-g12-u18.title":"动作","ko-g12-u18.tip":"以 요 结尾的词是礼貌说法。가요 可以是“我去”“你去”或“我们走吧”——看情况就知道！","ko-g12-u18.w.0":"去","ko-g12-u18.w.1":"来","ko-g12-u18.w.2":"吃","ko-g12-u18.w.3":"喝","ko-g12-u18.w.4":"睡觉","ko-g12-u18.w.5":"跑","ko-g12-u18.w.6":"读","ko-g12-u18.w.7":"看","ko-g12-u18.w.8":"坐","ko-g12-u18.s.0":"我喝水。","ko-g12-u18.s.1":"我看书。","ko-g12-u18.s.2":"快跑！","ko-g12-u18.s.3":"坐这里。","ko-g12-u18.s.4":"看天空。","ko-g12-u18.s.5":"我回家。","ko-g12-u19.title":"我们的社区","ko-g12-u19.tip":"很多地点词以 원、관、국 结尾——병원, 도서관, 우체국。它们来自表示建筑的古老汉字。","ko-g12-u19.w.0":"社区","ko-g12-u19.w.1":"商店","ko-g12-u19.w.2":"医院","ko-g12-u19.w.3":"公园","ko-g12-u19.w.4":"图书馆","ko-g12-u19.w.5":"面包店","ko-g12-u19.w.6":"邮局","ko-g12-u19.w.7":"游乐场","ko-g12-u19.w.8":"警察局","ko-g12-u19.s.0":"我去公园。","ko-g12-u19.s.1":"面包店很近。","ko-g12-u19.s.2":"我在图书馆看书。","ko-g12-u19.s.3":"我在游乐场玩。","ko-g12-u19.s.4":"医院在哪里？","ko-g12-u19.s.5":"商店很大。","ko-g12-u20.title":"生日派对","ko-g12-u20.tip":"韩国人过生日要喝 미역국（海带汤）——妈妈生完宝宝后会喝它，所以它代表“谢谢妈妈”。","ko-g12-u20.w.0":"生日","ko-g12-u20.w.1":"派对","ko-g12-u20.w.2":"礼物","ko-g12-u20.w.3":"蛋糕","ko-g12-u20.w.4":"蜡烛","ko-g12-u20.w.5":"歌","ko-g12-u20.w.6":"卡片","ko-g12-u20.w.7":"海带汤","ko-g12-u20.w.8":"祝贺","ko-g12-u20.s.0":"生日快乐！","ko-g12-u20.s.1":"谢谢你的礼物。","ko-g12-u20.s.2":"蛋糕很好吃。","ko-g12-u20.s.3":"我吹蜡烛。","ko-g12-u20.s.4":"我们一起唱歌。","ko-g12-u20.s.5":"我喝海带汤。"},u={"ko-g34-u01.title":"我是……：自我介绍","ko-g34-u01.tip":"看看词的最后一个方块字：학생 以 ㅇ 结尾，所以是 학생이에요。의사 没有收音，所以是 의사예요。","ko-g34-u01.w.0":"学生","ko-g34-u01.w.1":"医生","ko-g34-u01.w.2":"厨师","ko-g34-u01.w.3":"歌手","ko-g34-u01.w.4":"警察","ko-g34-u01.w.5":"名字","ko-g34-u01.w.6":"国家","ko-g34-u01.w.7":"人","ko-g34-u01.w.8":"韩国","ko-g34-u01.w.9":"我（礼貌）","ko-g34-u01.s.0":"我是小学生。","ko-g34-u01.s.1":"我的名字叫敏俊。","ko-g34-u01.s.2":"我是美国人。","ko-g34-u01.s.3":"我爸爸是医生。","ko-g34-u01.s.4":"这个人是我的朋友。","ko-g34-u01.s.5":"我十岁了。","ko-g34-u01.s.6":"老师是韩国人。","ko-g34-u01.s.7":"很高兴认识你。","ko-g34-u01.g.title":"介绍自己：이에요 / 예요","ko-g34-u01.g.x.0":"要说“A是B”，就在B后面直接加 이에요 或 예요：저는 학생이에요（我是学生）。","ko-g34-u01.g.x.1":"如果B以收音结尾，就用 이에요：학생이에요。没有收音就用 예요：의사예요。","ko-g34-u01.g.x.2":"礼貌地说话时，저 是“我”，제 是“我的”：제 이름은 지우예요。","ko-g34-u01.g.0":"我是学生。","ko-g34-u01.g.1":"我是医生。","ko-g34-u01.g.2":"我的名字叫瑞妍。","ko-g34-u01.g.3":"我是歌手。","ko-g34-u01.g.4":"我是韩国人。","ko-g34-u01.g.5":"我是厨师。","ko-g34-u01.g.5.task":"把 학생 换成 요리사（厨师）。","ko-g34-u01.g.6":"我妈妈是警察。","ko-g34-u01.g.6.task":"把 의사 换成 경찰（警察）。","ko-g34-u01.g.7":"我的朋友是加拿大人。","ko-g34-u01.g.7.task":"用 제 친구는（我的朋友）开头。","ko-g34-u01.st.title":"新朋友","ko-g34-u01.st.l.0":"你好！我是敏俊。","ko-g34-u01.st.l.1":"你好！我是艾玛。","ko-g34-u01.st.l.2":"艾玛，你是哪国人？","ko-g34-u01.st.l.3":"我是英国人。","ko-g34-u01.st.l.4":"很高兴认识你！","ko-g34-u01.st.l.5":"我也很高兴认识你。","ko-g34-u01.st.q.0":"艾玛是哪里人？","ko-g34-u01.st.q.0.o.0":"영국","ko-g34-u01.st.q.0.o.1":"한국","ko-g34-u01.st.q.0.o.2":"미국","ko-g34-u01.st.q.1":"男孩叫什么名字？","ko-g34-u01.st.q.1.o.0":"민준","ko-g34-u01.st.q.1.o.1":"엠마","ko-g34-u01.st.q.1.o.2":"지우","ko-g34-u02.title":"这是什么？","ko-g34-u02.tip":"边说边指吧！이거 在你手里，그거 在朋友手里，저거 离你们俩都很远。","ko-g34-u02.w.0":"钱包","ko-g34-u02.w.1":"眼镜","ko-g34-u02.w.2":"钥匙","ko-g34-u02.w.3":"手机","ko-g34-u02.w.4":"照片","ko-g34-u02.w.5":"东西","ko-g34-u02.w.6":"这个","ko-g34-u02.w.7":"那个（在你那边）","ko-g34-u02.w.8":"那个（在远处）","ko-g34-u02.w.9":"什么","ko-g34-u02.s.0":"你那个是什么？","ko-g34-u02.s.1":"这是我的钱包。","ko-g34-u02.s.2":"你那个是眼镜吗？","ko-g34-u02.s.3":"对，是眼镜。","ko-g34-u02.s.4":"那边那个是谁的？","ko-g34-u02.s.5":"那是老师的手机。","ko-g34-u02.s.6":"这副眼镜是爷爷的。","ko-g34-u02.s.7":"那边那个钱包是谁的？","ko-g34-u02.g.title":"这、那、远处的那：이 / 그 / 저","ko-g34-u02.g.x.0":"이 = 这（离我近），그 = 那（离你近），저 = 那（离我们俩都远）。","ko-g34-u02.g.x.1":"加上 거 表示“东西”：이거（这个）、그거、저거。也可以加名词：이 사진（这张照片）、저 가방（那个书包）。","ko-g34-u02.g.x.2":"用 뭐예요 来问：이거 뭐예요? ——这是什么？","ko-g34-u02.g.0":"这是什么？","ko-g34-u02.g.1":"那边那个是我的书包。","ko-g34-u02.g.2":"这张照片很漂亮。","ko-g34-u02.g.3":"请把那把钥匙给我。","ko-g34-u02.g.4":"你那个是我的手机。","ko-g34-u02.g.5":"这是铅笔。","ko-g34-u02.g.5.task":"把 그거 换成 이거（这个）。","ko-g34-u02.g.6":"那边那个是什么？","ko-g34-u02.g.6.task":"问远处的东西：用 저거。","ko-g34-u02.g.7":"这副眼镜很好看。","ko-g34-u02.g.7.task":"把 저 换成 이（这）。","ko-g34-u03.title":"我有、有……","ko-g34-u03.tip":"一个好用的词：只说 없어요 就能表示“我没有”或“没有”。문제 없어요! = 没问题！","ko-g34-u03.w.0":"钱","ko-g34-u03.w.1":"时间","ko-g34-u03.w.2":"兄弟姐妹","ko-g34-u03.w.3":"宠物","ko-g34-u03.w.4":"问题","ko-g34-u03.w.5":"约会（约好见面）","ko-g34-u03.w.6":"座位","ko-g34-u03.w.7":"糖果","ko-g34-u03.w.8":"感冒","ko-g34-u03.w.9":"票","ko-g34-u03.s.0":"我有弟弟或妹妹。","ko-g34-u03.s.1":"我的钱包里有一点钱。","ko-g34-u03.s.2":"你今天有时间吗？","ko-g34-u03.s.3":"家里有一只猫。","ko-g34-u03.s.4":"没问题。","ko-g34-u03.s.5":"我明天有约。","ko-g34-u03.s.6":"这个座位有人吗？","ko-g34-u03.s.7":"有一颗糖。","ko-g34-u03.g.title":"有·没有：있어요 · 없어요","ko-g34-u03.g.x.0":"있어요 表示“有”或“我有”，없어요 表示“没有”或“我没有”。","ko-g34-u03.g.x.1":"在东西后面加 이 或 가：有收音用 이（돈이），没有收音用 가（사과가）。","ko-g34-u03.g.x.2":"提问时句尾语调上扬：시간 있어요? ——你有时间吗？","ko-g34-u03.g.0":"我没有钱。","ko-g34-u03.g.1":"有一个苹果。","ko-g34-u03.g.2":"你有猫吗？","ko-g34-u03.g.3":"我没有时间。","ko-g34-u03.g.4":"我有约。","ko-g34-u03.g.5":"我没有兄弟姐妹。","ko-g34-u03.g.5.task":"改成“没有”：用 없어요。","ko-g34-u03.g.6":"这里有票。","ko-g34-u03.g.6.task":"把 사탕 换成 표（票）。注意 이/가！","ko-g34-u03.g.7":"你有宠物吗？","ko-g34-u03.g.7.task":"改成问句。","ko-g34-u04.title":"至于我：은 / 는","ko-g34-u04.tip":"在韩国，小朋友不直呼哥哥姐姐的名字，而是用这些称呼。男生说 형 和 누나，女生说 오빠 和 언니。","ko-g34-u04.w.0":"哥哥（男生叫）","ko-g34-u04.w.1":"哥哥（女生叫）","ko-g34-u04.w.2":"姐姐（男生叫）","ko-g34-u04.w.3":"姐姐（女生叫）","ko-g34-u04.w.4":"身高","ko-g34-u04.w.5":"头发","ko-g34-u04.w.6":"爱好","ko-g34-u04.w.7":"运动","ko-g34-u04.w.8":"音乐","ko-g34-u04.w.9":"性格","ko-g34-u04.s.0":"我哥哥十二岁。","ko-g34-u04.s.1":"我姐姐性格很好。","ko-g34-u04.s.2":"我个子矮。","ko-g34-u04.s.3":"我姐姐的爱好是唱歌。","ko-g34-u04.s.4":"我哥哥是短头发。","ko-g34-u04.s.5":"我喜欢音乐。","ko-g34-u04.s.6":"我哥哥每天运动。","ko-g34-u04.s.7":"猫咪很爱睡觉。","ko-g34-u04.g.title":"说话题：은 / 는","ko-g34-u04.g.x.0":"은/는 标出你在说的对象（话题）：저는 학생이에요——至于我，我是学生。","ko-g34-u04.g.x.1":"有收音用 은（형은），没有收音用 는（저는, 누나는）。","ko-g34-u04.g.x.2":"它也能表示对比：형은 커요. 저는 작아요.——哥哥很高，我却很矮。","ko-g34-u04.g.0":"我是智宇。","ko-g34-u04.g.1":"我哥哥个子很高。","ko-g34-u04.g.2":"我姐姐喜欢音乐。","ko-g34-u04.g.3":"猫咪很可爱。","ko-g34-u04.g.4":"我的爱好是画画。","ko-g34-u04.g.5":"我姐姐是长头发。","ko-g34-u04.g.5.task":"改成说姐姐（언니）。","ko-g34-u04.g.6":"我弟弟（妹妹）个子矮。","ko-g34-u04.g.6.task":"把 형 换成 동생。注意 은/는！","ko-g34-u04.g.7":"我哥哥很擅长运动。","ko-g34-u04.g.7.task":"说说哥哥（오빠）。","ko-g34-u05.title":"动词：요 结尾","ko-g34-u05.tip":"句尾的 요 让句子变得有礼貌。对大人和刚认识的人就用它——用 요 一定不会错！","ko-g34-u05.w.0":"买","ko-g34-u05.w.1":"见面","ko-g34-u05.w.2":"学习","ko-g34-u05.w.3":"玩","ko-g34-u05.w.4":"听","ko-g34-u05.w.5":"写","ko-g34-u05.w.6":"工作","ko-g34-u05.w.7":"等","ko-g34-u05.w.8":"学","ko-g34-u05.w.9":"好","ko-g34-u05.s.0":"我在学韩语。","ko-g34-u05.s.1":"我在公园见朋友。","ko-g34-u05.s.2":"我买面包。","ko-g34-u05.s.3":"弟弟（妹妹）在玩。","ko-g34-u05.s.4":"我听音乐。","ko-g34-u05.s.5":"妈妈在等着。","ko-g34-u05.s.6":"爸爸在工作。","ko-g34-u05.s.7":"我们一起学习吧。","ko-g34-u05.g.title":"礼貌的动词词尾：-아요 / -어요 / 해요","ko-g34-u05.g.x.0":"韩语动词会变词尾。去掉 다，加上 요 形词尾：가다 → 가요，먹다 → 먹어요。","ko-g34-u05.g.x.1":"如果最后的元音是 ㅏ 或 ㅗ，就加 아요：놀다 → 놀아요，보다 → 봐요。其他元音加 어요：먹다 → 먹어요。","ko-g34-u05.g.x.2":"以 하다 结尾的动词变成 해요：공부하다 → 공부해요。","ko-g34-u05.g.x.3":"有些元音会合在一起：기다리다 → 기다려요，마시다 → 마셔요。","ko-g34-u05.g.0":"我见朋友。","ko-g34-u05.g.1":"我吃饭。","ko-g34-u05.g.2":"我在游乐场玩。","ko-g34-u05.g.3":"我学习韩语。","ko-g34-u05.g.4":"我看书。","ko-g34-u05.g.5":"我买面包。","ko-g34-u05.g.5.task":"把 사다 改成礼貌的 요 形。","ko-g34-u05.g.6":"弟弟（妹妹）在等着。","ko-g34-u05.g.6.task":"把 기다리다 改成礼貌的 요 形。","ko-g34-u05.g.7":"爸爸在公司上班。","ko-g34-u05.g.7.task":"把 일하다 改成礼貌的 요 形。","ko-g34-u05.st.title":"星期六你做什么？","ko-g34-u05.st.l.0":"星期六你做什么？","ko-g34-u05.st.l.1":"我学游泳。","ko-g34-u05.st.l.2":"哇！我踢足球。","ko-g34-u05.st.l.3":"那星期天呢？","ko-g34-u05.st.l.4":"我去奶奶家。我们一起吃饭。","ko-g34-u05.st.l.5":"真好！我在家休息。","ko-g34-u05.st.q.0":"瑞妍星期六学什么？","ko-g34-u05.st.q.0.o.0":"수영","ko-g34-u05.st.q.0.o.1":"축구","ko-g34-u05.st.q.0.o.2":"피아노","ko-g34-u05.st.q.1":"敏俊星期天去哪里？","ko-g34-u05.st.q.1.o.0":"할머니 집","ko-g34-u05.st.q.1.o.1":"학교","ko-g34-u05.st.q.1.o.2":"공원","ko-g34-u06.title":"吃什么、看什么、做什么：을 / 를","ko-g34-u06.tip":"记住顺序：谁 → 什么 → 做。저는（我）피자를（披萨）먹어요（吃）。动作词永远放在最后！","ko-g34-u06.w.0":"电影","ko-g34-u06.w.1":"画","ko-g34-u06.w.2":"信","ko-g34-u06.w.3":"报纸","ko-g34-u06.w.4":"钢琴","ko-g34-u06.w.5":"足球","ko-g34-u06.w.6":"游泳","ko-g34-u06.w.7":"打扫","ko-g34-u06.w.8":"洗碗","ko-g34-u06.w.9":"咖啡","ko-g34-u06.s.0":"我和弟弟（妹妹）一起看电影。","ko-g34-u06.s.1":"我画画。","ko-g34-u06.s.2":"我给朋友写信。","ko-g34-u06.s.3":"我弹钢琴。","ko-g34-u06.s.4":"我踢足球。","ko-g34-u06.s.5":"爸爸洗碗。","ko-g34-u06.s.6":"妈妈喝咖啡。","ko-g34-u06.s.7":"我打扫房间。","ko-g34-u06.g.title":"动作的对象：을 / 를","ko-g34-u06.g.x.0":"을/를 标出宾语——也就是你吃的、看的或做的东西：사과를 먹어요（我吃苹果）。","ko-g34-u06.g.x.1":"有收音用 을（빵을），没有收音用 를（커피를）。","ko-g34-u06.g.x.2":"韩语把动词放在最后：저는 영화를 봐요 = 我·电影·看。","ko-g34-u06.g.0":"我看电影。","ko-g34-u06.g.1":"我吃面包。","ko-g34-u06.g.2":"我喝咖啡。","ko-g34-u06.g.3":"我写信。","ko-g34-u06.g.4":"我看报纸。","ko-g34-u06.g.5":"我弹钢琴。","ko-g34-u06.g.5.task":"把动词放在最后。","ko-g34-u06.g.6":"弟弟（妹妹）在画画。","ko-g34-u06.g.6.task":"把动词放在最后。","ko-g34-u06.g.7":"我哥哥去游泳。","ko-g34-u06.g.7.task":"把 축구（足球）换成 수영（游泳）。","ko-g34-u07.title":"不：안","ko-g34-u07.tip":"如果你不爱吃辣，这句话在韩国很有用：안 매운 거 있어요? ——有不辣的吗？","ko-g34-u07.w.0":"辣","ko-g34-u07.w.1":"贵","ko-g34-u07.w.2":"便宜","ko-g34-u07.w.3":"难","ko-g34-u07.w.4":"容易","ko-g34-u07.w.5":"忙","ko-g34-u07.w.6":"热（天气）","ko-g34-u07.w.7":"疼、不舒服","ko-g34-u07.w.8":"好吃","ko-g34-u07.w.9":"好玩","ko-g34-u07.s.0":"炒年糕有点辣。","ko-g34-u07.s.1":"这道题不简单。","ko-g34-u07.s.2":"这本书不贵。","ko-g34-u07.s.3":"爸爸喝咖啡。","ko-g34-u07.s.4":"作业不难。","ko-g34-u07.s.5":"今天不热。","ko-g34-u07.s.6":"已经不疼了。","ko-g34-u07.s.7":"电影真的很好看。","ko-g34-u07.g.title":"不：안 + 动词","ko-g34-u07.g.x.0":"在动词或形容词前面加 안，就表示“不”：매워요 → 안 매워요。","ko-g34-u07.g.x.1":"遇到 해요 动词，안 要放在 해요 的正前面：공부해요 → 공부 안 해요。","ko-g34-u07.g.x.2":"맛있어요 和 재미있어요 有自己专门的反义词：맛없어요、재미없어요。","ko-g34-u07.g.0":"泡菜不辣。","ko-g34-u07.g.1":"我不喝咖啡。","ko-g34-u07.g.2":"我今天不忙。","ko-g34-u07.g.3":"我不写作业。","ko-g34-u07.g.4":"这个披萨不好吃。","ko-g34-u07.g.5":"我不弹钢琴。","ko-g34-u07.g.5.task":"用 안 改成否定句。","ko-g34-u07.g.6":"今天不冷。","ko-g34-u07.g.6.task":"用 안 改成否定句。","ko-g34-u07.g.7":"我哥哥不运动。","ko-g34-u07.g.7.task":"改成否定句。안 要放在 해요 的正前面。","ko-g34-u08.title":"去某个地方：에 가요","ko-g34-u08.tip":"釜山是韩国海边的大城市，济州岛（제주도）是家庭旅行最爱去的地方。","ko-g34-u08.w.0":"市场","ko-g34-u08.w.1":"超市","ko-g34-u08.w.2":"游泳池","ko-g34-u08.w.3":"电影院","ko-g34-u08.w.4":"博物馆","ko-g34-u08.w.5":"动物园","ko-g34-u08.w.6":"公司","ko-g34-u08.w.7":"首尔","ko-g34-u08.w.8":"旅行","ko-g34-u08.w.9":"周末","ko-g34-u08.s.0":"我周末去动物园。","ko-g34-u08.s.1":"妈妈去市场。","ko-g34-u08.s.2":"爸爸去上班。","ko-g34-u08.s.3":"夏天我去游泳池。","ko-g34-u08.s.4":"你明天去哪里？","ko-g34-u08.s.5":"我去博物馆。","ko-g34-u08.s.6":"我明天去首尔。","ko-g34-u08.s.7":"我们一起去电影院吧！","ko-g34-u08.g.title":"去某处：에 가요 · 에 와요","ko-g34-u08.g.x.0":"在地点后面加 에，表示要去哪里：학교에 가요（我去学校）。","ko-g34-u08.g.x.1":"不管有没有收音，에 都不变：시장에、마트에。","ko-g34-u08.g.x.2":"用 어디 来问：어디에 가요? ——你去哪里？“来”用 와요：집에 와요。","ko-g34-u08.g.0":"我去学校。","ko-g34-u08.g.1":"我去动物园。","ko-g34-u08.g.2":"你去哪里？","ko-g34-u08.g.3":"朋友来我家。","ko-g34-u08.g.4":"我们去游泳池。","ko-g34-u08.g.5":"我明天去博物馆。","ko-g34-u08.g.5.task":"把 극장（电影院）换成 박물관（博物馆）。","ko-g34-u08.g.6":"妈妈去市场。","ko-g34-u08.g.6.task":"把 마트 换成 시장（市场）。","ko-g34-u08.g.7":"朋友来我们家。","ko-g34-u08.g.7.task":"把 가요（去）换成 와요（来）。","ko-g34-u08.st.title":"周末计划","ko-g34-u08.st.l.0":"这个周末你去哪里？","ko-g34-u08.st.l.1":"我去动物园。那里有熊猫！","ko-g34-u08.st.l.2":"哇，真好！你跟谁去？","ko-g34-u08.st.l.3":"跟爸爸和弟弟（妹妹）一起。智宇你呢？","ko-g34-u08.st.l.4":"我去奶奶家。她住在釜山。","ko-g34-u08.st.l.5":"釜山的海好美！","ko-g34-u08.st.q.0":"河俊要去哪里？","ko-g34-u08.st.q.0.o.0":"동물원","ko-g34-u08.st.q.0.o.1":"바다","ko-g34-u08.st.q.0.o.2":"시장","ko-g34-u08.st.q.1":"智宇的奶奶住在哪里？","ko-g34-u08.st.q.1.o.0":"부산","ko-g34-u08.st.q.1.o.1":"서울","ko-g34-u08.st.q.1.o.2":"제주도","ko-g34-u09.title":"在哪里？","ko-g34-u09.tip":"用玩具玩捉迷藏：把玩具藏起来，用韩语给提示——의자 아래에 있어요! 책상 위에 있어요!","ko-g34-u09.w.0":"上面","ko-g34-u09.w.1":"下面","ko-g34-u09.w.2":"旁边","ko-g34-u09.w.3":"前面","ko-g34-u09.w.4":"后面","ko-g34-u09.w.5":"里面","ko-g34-u09.w.6":"外面","ko-g34-u09.w.7":"这里","ko-g34-u09.w.8":"那里（你那边）","ko-g34-u09.w.9":"那边（远处）","ko-g34-u09.s.0":"猫在床上。","ko-g34-u09.s.1":"猫在沙发下面。","ko-g34-u09.s.2":"铅笔在书包里。","ko-g34-u09.s.3":"我家前面有个公园。","ko-g34-u09.s.4":"妈妈坐在我旁边。","ko-g34-u09.s.5":"小狗在门后面。","ko-g34-u09.s.6":"卫生间在那边。","ko-g34-u09.s.7":"妈妈在外面。","ko-g34-u09.g.title":"东西在哪里：에 있어요 · 위 / 아래 / 옆","ko-g34-u09.g.x.0":"用 에 있어요 说东西在哪里：고양이가 방에 있어요（猫在房间里）。","ko-g34-u09.g.x.1":"要说准确的位置，先说东西，再说方位，最后加 에：책상 위에（在书桌上），의자 아래에（在椅子下面）。","ko-g34-u09.g.x.2":"方位词：위 上面，아래 下面，옆 旁边，앞 前面，뒤 后面，안 里面，밖 外面。","ko-g34-u09.g.0":"书在书桌上。","ko-g34-u09.g.1":"球在椅子下面。","ko-g34-u09.g.2":"猫在箱子里。","ko-g34-u09.g.3":"朋友在我旁边。","ko-g34-u09.g.4":"树后面有一只小狗。","ko-g34-u09.g.5":"牛奶在冰箱里。","ko-g34-u09.g.5.task":"把牛奶放进冰箱里：用 안。","ko-g34-u09.g.6":"公园在学校前面。","ko-g34-u09.g.6.task":"把公园移到学校前面：用 앞。","ko-g34-u09.g.7":"鞋子在门旁边吗？","ko-g34-u09.g.7.task":"改成问句。","ko-g34-u10.title":"在哪里做：에서","ko-g34-u10.tip":"에 用在去某处或在某处（학교에 가요）。에서 用在在那里做事（학교에서 공부해요）。","ko-g34-u10.w.0":"操场","ko-g34-u10.w.1":"餐厅","ko-g34-u10.w.2":"咖啡馆","ko-g34-u10.w.3":"海边","ko-g34-u10.w.4":"体育馆","ko-g34-u10.w.5":"篮球","ko-g34-u10.w.6":"画","ko-g34-u10.w.7":"休息","ko-g34-u10.w.8":"拍（照片）","ko-g34-u10.w.9":"唱歌","ko-g34-u10.s.0":"我在操场上玩。","ko-g34-u10.s.1":"我在餐厅吃冷面。","ko-g34-u10.s.2":"我在图书馆看书。","ko-g34-u10.s.3":"我在海边堆沙堡。","ko-g34-u10.s.4":"我在家休息。","ko-g34-u10.s.5":"我在公园画画。","ko-g34-u10.s.6":"我在体育馆跳绳。","ko-g34-u10.s.7":"我们在哪里见面？","ko-g34-u10.g.title":"动作发生的地方：에서","ko-g34-u10.g.x.0":"在做事的地点后面加 에서：식당에서 먹어요（我在餐厅吃饭）。","ko-g34-u10.g.x.1":"가요、와요 和 있어요 要用 에：식당에 가요，식당에 있어요。","ko-g34-u10.g.x.2":"简单判断：如果有人在那里做动作，就用 에서。","ko-g34-u10.g.0":"我在餐厅吃饭。","ko-g34-u10.g.1":"我在操场上踢足球。","ko-g34-u10.g.2":"我在咖啡馆喝果汁。","ko-g34-u10.g.3":"我去图书馆。","ko-g34-u10.g.4":"哥哥在他的房间里。","ko-g34-u10.g.5":"我在海边拍照。","ko-g34-u10.g.5.task":"把 공원（公园）换成 바닷가（海边）。","ko-g34-u10.g.6":"我和朋友在家玩。","ko-g34-u10.g.6.task":"改成“在家玩”：用 에서 和 놀아요。","ko-g34-u10.g.7":"我在体育馆打篮球。","ko-g34-u10.g.7.task":"说说你在那里做什么：농구를 해요（打篮球）。","ko-g34-u11.title":"数东西","ko-g34-u11.tip":"钱用的是另一套数字（천 = 1,000）：삼천 원 是 3,000 韩元。数东西用 한, 두, 세, 네。","ko-g34-u11.w.0":"一（量词前）","ko-g34-u11.w.1":"二（量词前）","ko-g34-u11.w.2":"三（量词前）","ko-g34-u11.w.3":"四（量词前）","ko-g34-u11.w.4":"个（数人）","ko-g34-u11.w.5":"只（数动物）","ko-g34-u11.w.6":"本（数书）","ko-g34-u11.w.7":"张（数纸）","ko-g34-u11.w.8":"岁（数年龄）","ko-g34-u11.w.9":"几个","ko-g34-u11.s.0":"请给我一个苹果。","ko-g34-u11.s.1":"我家有四口人。","ko-g34-u11.s.2":"有两只猫。","ko-g34-u11.s.3":"你几岁了？","ko-g34-u11.s.4":"我九岁了。","ko-g34-u11.s.5":"我读三本书。","ko-g34-u11.s.6":"请给我一张纸。","ko-g34-u11.s.7":"有十个学生。","ko-g34-u11.g.title":"数数：数字 + 量词","ko-g34-u11.g.x.0":"韩语在数字后面加量词来数：사과 두 개（两个苹果），학생 세 명（三个学生）。","ko-g34-u11.g.x.1":"하나, 둘, 셋, 넷 在量词前会变短：한, 두, 세, 네。","ko-g34-u11.g.x.2":"量词：개 东西，명 人，마리 动物，권 书，장 纸，살 岁数。","ko-g34-u11.g.0":"请给我两个苹果。","ko-g34-u11.g.1":"有三个学生。","ko-g34-u11.g.2":"有一只小狗。","ko-g34-u11.g.3":"我八岁了。","ko-g34-u11.g.4":"有四本书。","ko-g34-u11.g.5":"有三只猫。","ko-g34-u11.g.5.task":"改成三只猫。","ko-g34-u11.g.6":"请给我两张纸。","ko-g34-u11.g.6.task":"要两张。","ko-g34-u11.g.7":"有四个朋友要来。","ko-g34-u11.g.7.task":"改成四个朋友。","ko-g34-u11.st.title":"在面包店","ko-g34-u11.st.l.0":"你好！我要两个面包。","ko-g34-u11.st.l.1":"要哪种面包？","ko-g34-u11.st.l.2":"这个奶油面包一个，那个巧克力面包一个。","ko-g34-u11.st.l.3":"给你。一共 3,000 韩元。","ko-g34-u11.st.l.4":"再要一瓶牛奶。","ko-g34-u11.st.l.5":"好的，一共 4,000 韩元。","ko-g34-u11.st.q.0":"瑞妍买了几个面包？","ko-g34-u11.st.q.0.o.0":"두 개","ko-g34-u11.st.q.0.o.1":"세 개","ko-g34-u11.st.q.0.o.2":"한 개","ko-g34-u11.st.q.1":"她还买了什么？","ko-g34-u11.st.q.1.o.0":"우유","ko-g34-u11.st.q.1.o.1":"주스","ko-g34-u11.st.q.1.o.2":"케이크","ko-g34-u12.title":"现在几点？","ko-g34-u12.tip":"几“点”用 한, 두, 세（数东西的数字），几“分”用 일, 이, 삼（另一套数字）。所以 3:10 是 세 시 십 분。","ko-g34-u12.w.0":"点（钟）","ko-g34-u12.w.1":"分","ko-g34-u12.w.2":"半","ko-g34-u12.w.3":"现在","ko-g34-u12.w.4":"上午","ko-g34-u12.w.5":"下午","ko-g34-u12.w.6":"午饭","ko-g34-u12.w.7":"傍晚、晚饭","ko-g34-u12.w.8":"早","ko-g34-u12.w.9":"晚","ko-g34-u12.s.0":"现在几点？","ko-g34-u12.s.1":"一点了。","ko-g34-u12.s.2":"我们两点半见吧。","ko-g34-u12.s.3":"我早上八点去学校。","ko-g34-u12.s.4":"我一点吃午饭。","ko-g34-u12.s.5":"我们下午四点见吧。","ko-g34-u12.s.6":"我傍晚写作业。","ko-g34-u12.s.7":"我今天很晚睡。","ko-g34-u12.g.title":"说时间：몇 시예요?","ko-g34-u12.g.x.0":"几“点”用短的数东西的数字 + 시：한 시、두 시、세 시、열두 시。","ko-g34-u12.g.x.1":"“半”是 반：두 시 반（两点半）。“分”用另一套数字：오 분、십 분。","ko-g34-u12.g.x.2":"加上 에 表示“在……时”：일곱 시에 일어나요（我七点起床）。","ko-g34-u12.g.0":"现在一点。","ko-g34-u12.g.1":"三点半了。","ko-g34-u12.g.2":"我七点起床。","ko-g34-u12.g.3":"我十二点吃午饭。","ko-g34-u12.g.4":"我们几点见？","ko-g34-u12.g.5":"我四点回家。","ko-g34-u12.g.5.task":"把时间改成四点。","ko-g34-u12.g.6":"五点半了。","ko-g34-u12.g.6.task":"加半个小时：用 반。","ko-g34-u12.g.7":"我九点睡觉。","ko-g34-u12.g.7.task":"说你九点睡觉：用 에 和 자요。","ko-g34-u13.title":"谁？哪里？什么时候？为什么？","ko-g34-u13.tip":"在韩国商店最有用的问题：이거 얼마예요?（这个多少钱？）在家玩开商店游戏时问问看！","ko-g34-u13.w.0":"谁","ko-g34-u13.w.1":"哪里","ko-g34-u13.w.2":"什么时候","ko-g34-u13.w.3":"为什么","ko-g34-u13.w.4":"怎么","ko-g34-u13.w.5":"什么样的","ko-g34-u13.w.6":"多少钱","ko-g34-u13.w.7":"哪个","ko-g34-u13.w.8":"理由","ko-g34-u13.w.9":"回答","ko-g34-u13.s.0":"那个人是谁？","ko-g34-u13.s.1":"什么时候放假？","ko-g34-u13.s.2":"你为什么难过？","ko-g34-u13.s.3":"去图书馆怎么走？","ko-g34-u13.s.4":"这个多少钱？","ko-g34-u13.s.5":"你喜欢什么食物？","ko-g34-u13.s.6":"你是哪国人？","ko-g34-u13.s.7":"卫生间在哪里？","ko-g34-u13.g.title":"疑问词：누구, 어디, 언제, 왜, 어떻게, 얼마","ko-g34-u13.g.x.0":"누구 谁 · 뭐 什么 · 어디 哪里 · 언제 什么时候 · 왜 为什么 · 어떻게 怎么 · 얼마 多少钱。","ko-g34-u13.g.x.1":"和 이에요/예요 一起用时放在句尾：누구예요? 어디예요? 얼마예요?","ko-g34-u13.g.x.2":"和其他动词一起用时放在动词前面：어디에 가요? 왜 울어요?","ko-g34-u13.g.0":"这个人是谁？","ko-g34-u13.g.1":"你的生日是什么时候？","ko-g34-u13.g.2":"你为什么哭？","ko-g34-u13.g.3":"这个苹果多少钱？","ko-g34-u13.g.4":"你怎么去学校？","ko-g34-u13.g.5":"你去哪里？","ko-g34-u13.g.5.task":"问“哪里”：用 어디에。","ko-g34-u13.g.6":"你什么时候来？","ko-g34-u13.g.6.task":"问“什么时候”：用 언제。","ko-g34-u13.g.7":"那个人是谁？","ko-g34-u13.g.7.task":"问“谁”：用 누구예요。","ko-g34-u14.title":"我想……","ko-g34-u14.tip":"你想做什么？用 -고 싶어요 说三句关于这个周末的话吧。","ko-g34-u14.w.0":"梦想","ko-g34-u14.w.1":"科学家","ko-g34-u14.w.2":"画家","ko-g34-u14.w.3":"运动员","ko-g34-u14.w.4":"太空","ko-g34-u14.w.5":"游乐园","ko-g34-u14.w.6":"炒年糕（辣的）","ko-g34-u14.w.7":"养","ko-g34-u14.w.8":"飞","ko-g34-u14.w.9":"雪人","ko-g34-u14.s.0":"我想成为科学家。","ko-g34-u14.s.1":"我想去太空。","ko-g34-u14.s.2":"我想吃炒年糕。","ko-g34-u14.s.3":"我想养猫。","ko-g34-u14.s.4":"我想去游乐园。","ko-g34-u14.s.5":"这个周末你想做什么？","ko-g34-u14.s.6":"我今天想休息。","ko-g34-u14.s.7":"我的梦想是当画家。","ko-g34-u14.g.title":"想做某事：-고 싶어요","ko-g34-u14.g.x.0":"要说想做什么，就去掉 다，加上 고 싶어요：먹다 → 먹고 싶어요（我想吃）。","ko-g34-u14.g.x.1":"不管有没有收音，每个动词都一样：가고 싶어요、놀고 싶어요、쉬고 싶어요。","ko-g34-u14.g.x.2":"“想成为”是 되고 싶어요：의사가 되고 싶어요（我想成为医生）。","ko-g34-u14.g.0":"我想吃披萨。","ko-g34-u14.g.1":"我想去海边。","ko-g34-u14.g.2":"我想成为画家。","ko-g34-u14.g.3":"我想和朋友玩。","ko-g34-u14.g.4":"你想做什么？","ko-g34-u14.g.5":"我想去太空。","ko-g34-u14.g.5.task":"说你想做：用 -고 싶어요。","ko-g34-u14.g.6":"我想养小狗。","ko-g34-u14.g.6.task":"说你想做：用 -고 싶어요。","ko-g34-u14.g.7":"我想堆雪人。","ko-g34-u14.g.7.task":"说你想做：用 -고 싶어요。","ko-g34-u14.st.title":"我的梦想","ko-g34-u14.st.l.0":"同学们，你们的梦想是什么？","ko-g34-u14.st.l.1":"我想成为足球运动员！","ko-g34-u14.st.l.2":"我想成为科学家。我想去太空。","ko-g34-u14.st.l.3":"我想成为画家。","ko-g34-u14.st.l.4":"大家的梦想都很棒！","ko-g34-u14.st.q.0":"瑞妍想成为什么？","ko-g34-u14.st.q.0.o.0":"과학자","ko-g34-u14.st.q.0.o.1":"화가","ko-g34-u14.st.q.0.o.2":"축구 선수","ko-g34-u14.st.q.1":"谁想成为画家？","ko-g34-u14.st.q.1.o.0":"지우","ko-g34-u14.st.q.1.o.1":"민준","ko-g34-u14.st.q.1.o.2":"서연","ko-g34-u15.title":"喜欢和讨厌","ko-g34-u15.tip":"和家人一起做一张“喜欢/讨厌”清单吧：아빠는 커피를 좋아해요. 저는 벌레를 싫어해요!","ko-g34-u15.w.0":"喜欢","ko-g34-u15.w.1":"讨厌","ko-g34-u15.w.2":"胡萝卜","ko-g34-u15.w.3":"蔬菜","ko-g34-u15.w.4":"辣椒","ko-g34-u15.w.5":"巧克力","ko-g34-u15.w.6":"童话","ko-g34-u15.w.7":"动画、漫画","ko-g34-u15.w.8":"虫子","ko-g34-u15.w.9":"最","ko-g34-u15.s.0":"我喜欢巧克力。","ko-g34-u15.s.1":"爸爸喜欢胡萝卜。","ko-g34-u15.s.2":"你喜欢什么童话？","ko-g34-u15.s.3":"我姐姐怕虫子。","ko-g34-u15.s.4":"我哥哥喜欢童话。","ko-g34-u15.s.5":"我最喜欢西瓜。","ko-g34-u15.s.6":"我也喜欢蔬菜。","ko-g34-u15.s.7":"辣椒太辣了。","ko-g34-u15.g.title":"喜欢和讨厌：좋아해요 · 싫어해요","ko-g34-u15.g.x.0":"喜欢的东西用 을/를 좋아해요：사과를 좋아해요。","ko-g34-u15.g.x.1":"讨厌的东西用 을/를 싫어해요：벌레를 싫어해요。","ko-g34-u15.g.x.2":"좋아요 也表示“我喜欢”：이 노래가 좋아요。用 좋아요 时要用 이/가，不用 을/를。","ko-g34-u15.g.0":"我喜欢猫。","ko-g34-u15.g.1":"弟弟（妹妹）讨厌胡萝卜。","ko-g34-u15.g.2":"我喜欢巧克力。","ko-g34-u15.g.3":"我喜欢这首歌。","ko-g34-u15.g.4":"你喜欢什么动画片？","ko-g34-u15.g.5":"我讨厌虫子。","ko-g34-u15.g.5.task":"说你讨厌它们。","ko-g34-u15.g.6":"我哥哥喜欢蔬菜。","ko-g34-u15.g.6.task":"把 고기（肉）换成 채소（蔬菜）。","ko-g34-u15.g.7":"我最喜欢草莓。","ko-g34-u15.g.7.task":"说“最”：加上 제일。","ko-g34-u16.title":"昨天我……：过去时","ko-g34-u16.tip":"注意听过去时里的 ㅆ 音：갔어요、봤어요、했어요。这个 ㅆ 就像小小的“了”！","ko-g34-u16.w.0":"上周","ko-g34-u16.w.1":"刚才","ko-g34-u16.w.2":"做了","ko-g34-u16.w.3":"去了","ko-g34-u16.w.4":"吃了","ko-g34-u16.w.5":"看了","ko-g34-u16.w.6":"来了","ko-g34-u16.w.7":"睡了","ko-g34-u16.w.8":"很好玩","ko-g34-u16.w.9":"寒暑假","ko-g34-u16.s.0":"我昨天看了电影。","ko-g34-u16.s.1":"我早上吃了面包。","ko-g34-u16.s.2":"我上周去了釜山。","ko-g34-u16.s.3":"我把作业都写完了。","ko-g34-u16.s.4":"朋友来我家了。","ko-g34-u16.s.5":"我昨晚很早就睡了。","ko-g34-u16.s.6":"假期真的很好玩。","ko-g34-u16.s.7":"我刚才见到妈妈了。","ko-g34-u16.g.title":"过去时：-았어요 / -었어요 / 했어요","ko-g34-u16.g.x.0":"要说过去，就改变 요 词尾：가요 → 갔어요，먹어요 → 먹었어요。","ko-g34-u16.g.x.1":"最后元音是 ㅏ 或 ㅗ 的动词加 았어요（놀다 → 놀았어요，보다 → 봤어요）。其他动词加 었어요（먹다 → 먹었어요）。","ko-g34-u16.g.x.2":"하다 动词变成 했어요：공부하다 → 공부했어요。","ko-g34-u16.g.0":"我昨天去了公园。","ko-g34-u16.g.1":"我吃了早饭。","ko-g34-u16.g.2":"我看了电影。","ko-g34-u16.g.3":"我写了作业。","ko-g34-u16.g.4":"我和朋友玩了。","ko-g34-u16.g.5":"我看了书。","ko-g34-u16.g.5.task":"改成过去时。","ko-g34-u16.g.6":"弟弟（妹妹）很早就睡了。","ko-g34-u16.g.6.task":"改成过去时。","ko-g34-u16.g.7":"爸爸做了饭。","ko-g34-u16.g.7.task":"改成过去时。","ko-g34-u16.st.title":"假期过得怎么样？","ko-g34-u16.st.l.0":"假期过得好吗？","ko-g34-u16.st.l.1":"嗯！我去了济州岛。","ko-g34-u16.st.l.2":"哇，你在济州岛做了什么？","ko-g34-u16.st.l.3":"我在海里游泳了，还吃了好多橘子。","ko-g34-u16.st.l.4":"我待在奶奶家，和小狗一起玩。","ko-g34-u16.st.l.5":"假期真的太好玩了！","ko-g34-u16.st.q.0":"河俊去了哪里？","ko-g34-u16.st.q.0.o.0":"제주도","ko-g34-u16.st.q.0.o.1":"서울","ko-g34-u16.st.q.0.o.2":"할머니 집","ko-g34-u16.st.q.1":"智宇和什么一起玩了？","ko-g34-u16.st.q.1.o.0":"강아지","ko-g34-u16.st.q.1.o.1":"고양이","ko-g34-u16.st.q.1.o.2":"공","ko-g34-u17.title":"我将要……：将来时","ko-g34-u17.tip":"过去、现在、将来：갔어요（去了）→ 가요（去）→ 갈 거예요（将要去）。用 먹다 和 하다 也说说这三种吧！","ko-g34-u17.w.0":"下周","ko-g34-u17.w.1":"明年","ko-g34-u17.w.2":"计划","ko-g34-u17.w.3":"考试","ko-g34-u17.w.4":"露营","ko-g34-u17.w.5":"帐篷","ko-g34-u17.w.6":"练习","ko-g34-u17.w.7":"搬家","ko-g34-u17.w.8":"大概","ko-g34-u17.w.9":"马上","ko-g34-u17.s.0":"我明天要去露营。","ko-g34-u17.s.1":"我周末要练钢琴。","ko-g34-u17.s.2":"大概会下雨。","ko-g34-u17.s.3":"下周有考试。","ko-g34-u17.s.4":"我要睡在帐篷里。","ko-g34-u17.s.5":"我们马上要吃晚饭了。","ko-g34-u17.s.6":"我明年就十岁了。","ko-g34-u17.s.7":"假期你要做什么？","ko-g34-u17.g.title":"将来时：-(으)ㄹ 거예요","ko-g34-u17.g.x.0":"说将来的事，就去掉 다，加上 ㄹ 거예요：가다 → 갈 거예요，하다 → 할 거예요。","ko-g34-u17.g.x.1":"如果词干以收音结尾，就加 을 거예요：먹다 → 먹을 거예요，읽다 → 읽을 거예요。","ko-g34-u17.g.x.2":"它也可以表示“大概”：비가 올 거예요（大概会下雨）。","ko-g34-u17.g.0":"我明天要去公园。","ko-g34-u17.g.1":"我晚饭要吃披萨。","ko-g34-u17.g.2":"我周末要学习。","ko-g34-u17.g.3":"大概会下雪。","ko-g34-u17.g.4":"我要看书。","ko-g34-u17.g.5":"我明天要见朋友。","ko-g34-u17.g.5.task":"改成明天：用 내일 和 -ㄹ 거예요。","ko-g34-u17.g.6":"我要去露营。","ko-g34-u17.g.6.task":"改成将来时。","ko-g34-u17.g.7":"假期我要学游泳。","ko-g34-u17.g.7.task":"改成将来时。","ko-g34-u18.title":"和、跟、也","ko-g34-u18.tip":"用一个长长的句子说说你早上做的事：일어나고, 씻고, 옷을 입고, 학교에 가요!","ko-g34-u18.w.0":"起床","ko-g34-u18.w.1":"洗","ko-g34-u18.w.2":"穿（衣服）","ko-g34-u18.w.3":"刷牙","ko-g34-u18.w.4":"整理","ko-g34-u18.w.5":"洗澡","ko-g34-u18.w.6":"然后","ko-g34-u18.w.7":"和、跟","ko-g34-u18.w.8":"也","ko-g34-u18.w.9":"一起","ko-g34-u18.s.0":"我起床后洗脸。","ko-g34-u18.s.1":"我洗完手再吃饭。","ko-g34-u18.s.2":"我吃牛奶和苹果。","ko-g34-u18.s.3":"我也一起去。","ko-g34-u18.s.4":"我穿上袜子出门。","ko-g34-u18.s.5":"我整理好房间再休息。","ko-g34-u18.s.6":"我和爸爸去公园。","ko-g34-u18.s.7":"我看完书就睡觉。","ko-g34-u18.g.title":"和：-고 · 하고 · 도","ko-g34-u18.g.x.0":"连接两个动作时，去掉 다 加上 고：먹다 → 먹고。밥을 먹고 양치해요（我吃完饭刷牙）。","ko-g34-u18.g.x.1":"连接两个名词用 하고：빵하고 우유（面包和牛奶）。하고 也有“跟”的意思：엄마하고 가요。","ko-g34-u18.g.x.2":"도 表示“也”，用来代替 은/는、이/가 或 을/를：저도 좋아요（我也喜欢）。","ko-g34-u18.g.0":"我吃完饭然后刷牙。","ko-g34-u18.g.1":"我穿好衣服去学校。","ko-g34-u18.g.2":"我吃面包和牛奶。","ko-g34-u18.g.3":"我也想去。","ko-g34-u18.g.4":"我和妈妈去市场。","ko-g34-u18.g.5":"我写完作业再玩。","ko-g34-u18.g.5.task":"用 -고 把两个句子连起来。","ko-g34-u18.g.6":"我洗完澡再睡觉。","ko-g34-u18.g.6.task":"用 -고 把两个句子连起来。","ko-g34-u18.g.7":"弟弟（妹妹）也要来。","ko-g34-u18.g.7.task":"说“也”：用 도。","ko-g34-u19.title":"请……","ko-g34-u19.tip":"在韩国有两句魔法用语：주세요（请给我）和 천천히 말해 주세요（请说慢一点）。笑着说出来吧！","ko-g34-u19.w.0":"请给我","ko-g34-u19.w.1":"请（让请求更委婉）","ko-g34-u19.w.2":"请坐","ko-g34-u19.w.3":"请过来","ko-g34-u19.w.4":"请等一下","ko-g34-u19.w.5":"安静地","ko-g34-u19.w.6":"慢慢地","ko-g34-u19.w.7":"再一次","ko-g34-u19.w.8":"一会儿","ko-g34-u19.w.9":"请帮帮我","ko-g34-u19.s.0":"请给我一杯牛奶。","ko-g34-u19.s.1":"请坐。","ko-g34-u19.s.2":"欢迎，请进。","ko-g34-u19.s.3":"请在这里等。","ko-g34-u19.s.4":"请走慢一点。","ko-g34-u19.s.5":"请再说一遍。","ko-g34-u19.s.6":"在图书馆请保持安静。","ko-g34-u19.s.7":"请帮帮我！","ko-g34-u19.g.title":"请做：-(으)세요 · -아/어 주세요","ko-g34-u19.g.x.0":"礼貌地请别人做事，就去掉 다 加上 세요：가다 → 가세요，오다 → 오세요。","ko-g34-u19.g.x.1":"如果词干以收音结尾，就加 으세요：앉다 → 앉으세요，읽다 → 읽으세요。","ko-g34-u19.g.x.2":"请别人为你做事，用 -아/어 주세요：도와주세요（请帮帮我），말해 주세요（请告诉我）。","ko-g34-u19.g.0":"请坐这里。","ko-g34-u19.g.1":"请往这边走。","ko-g34-u19.g.2":"请读这本书。","ko-g34-u19.g.3":"请说慢一点。","ko-g34-u19.g.4":"请给我一些水。","ko-g34-u19.g.5":"请稍等一下。","ko-g34-u19.g.5.task":"改成礼貌的请求：用 -세요。","ko-g34-u19.g.6":"请洗手。","ko-g34-u19.g.6.task":"改成礼貌的请求：用 -으세요。","ko-g34-u19.g.7":"请再说一遍。","ko-g34-u19.g.7.task":"请别人帮忙：用 주세요。","ko-g34-u19.st.title":"在餐厅","ko-g34-u19.st.l.0":"欢迎光临！几位？","ko-g34-u19.st.l.1":"三位。","ko-g34-u19.st.l.2":"请往这边走，请坐这里。","ko-g34-u19.st.l.3":"请给我一份拌饭和两份紫菜包饭。","ko-g34-u19.st.l.4":"好的，请稍等。","ko-g34-u19.st.l.5":"也请给我们一些水！","ko-g34-u19.st.q.0":"这家人有几个人？","ko-g34-u19.st.q.0.o.0":"세 명","ko-g34-u19.st.q.0.o.1":"두 명","ko-g34-u19.st.q.0.o.2":"네 명","ko-g34-u19.st.q.1":"瑞妍点了什么？","ko-g34-u19.st.q.1.o.0":"비빔밥하고 김밥","ko-g34-u19.st.q.1.o.1":"떡볶이하고 라면","ko-g34-u19.st.q.1.o.2":"김밥 세 개","ko-g34-u20.title":"非常、一点、太","ko-g34-u20.tip":"玩反义词游戏：一个人说 커요!，另一个人就回答 작아요!。接着试试 빨라요 → 느려요。","ko-g34-u20.w.0":"大","ko-g34-u20.w.1":"小","ko-g34-u20.w.2":"长","ko-g34-u20.w.3":"短","ko-g34-u20.w.4":"重","ko-g34-u20.w.5":"轻","ko-g34-u20.w.6":"快","ko-g34-u20.w.7":"慢","ko-g34-u20.w.8":"非常","ko-g34-u20.w.9":"太","ko-g34-u20.s.0":"鲸鱼真的很大。","ko-g34-u20.s.1":"老鼠非常小。","ko-g34-u20.s.2":"这本书有点重。","ko-g34-u20.s.3":"乌龟非常慢。","ko-g34-u20.s.4":"火车太快了。","ko-g34-u20.s.5":"气球很轻。","ko-g34-u20.s.6":"弟弟（妹妹）的头发很长。","ko-g34-u20.s.7":"这支铅笔太短了。","ko-g34-u20.g.title":"非常、一点、太：아주 · 조금 · 너무","ko-g34-u20.g.x.0":"形容词本身就能像动词一样用：커요（很大），빨라요（很快）。","ko-g34-u20.g.x.1":"在它们前面加 아주（非常）、조금（一点）或 너무（太）：아주 커요，조금 작아요，너무 무거워요。","ko-g34-u20.g.x.2":"成对地记住它们：커요 ↔ 작아요，길어요 ↔ 짧아요，빨라요 ↔ 느려요，무거워요 ↔ 가벼워요。","ko-g34-u20.g.0":"大象非常大。","ko-g34-u20.g.1":"书包太重了。","ko-g34-u20.g.2":"蜗牛很慢。","ko-g34-u20.g.3":"我的头发有点短。","ko-g34-u20.g.4":"猎豹真的很快。","ko-g34-u20.g.5":"这条裤子太长了。","ko-g34-u20.g.5.task":"说“太长”：加上 너무。","ko-g34-u20.g.6":"蚂蚁非常小。","ko-g34-u20.g.6.task":"改成相反的意思。","ko-g34-u20.g.7":"羽毛非常轻。","ko-g34-u20.g.7.task":"说“非常轻”：加上 아주。"},s={"ko-g56-u01.title":"正在做：-고 있어요","ko-g56-u01.tip":"看看四周，说说大家现在正在做什么：아빠는 요리하고 있어요. 고양이는 자고 있어요.","ko-g56-u01.w.0":"最近","ko-g56-u01.w.1":"吉他","ko-g56-u01.w.2":"电话","ko-g56-u01.w.3":"准备","ko-g56-u01.w.4":"散步","ko-g56-u01.w.5":"午觉","ko-g56-u01.w.6":"洗衣服","ko-g56-u01.w.7":"短信","ko-g56-u01.w.8":"发送","ko-g56-u01.w.9":"找","ko-g56-u01.w.10":"做、制作","ko-g56-u01.w.11":"笑","ko-g56-u01.s.0":"你现在在做什么？","ko-g56-u01.s.1":"弟弟（妹妹）在睡午觉。","ko-g56-u01.s.2":"妈妈在打电话。","ko-g56-u01.s.3":"我最近在学吉他。","ko-g56-u01.s.4":"爸爸在洗衣服。","ko-g56-u01.s.5":"哥哥在给朋友打电话。","ko-g56-u01.s.6":"奶奶在和小狗散步。","ko-g56-u01.s.7":"我在准备去上学。","ko-g56-u01.g.title":"正在发生：-고 있어요","ko-g56-u01.g.x.0":"要说正在做的事，就去掉 다 加上 고 있어요：먹다 → 먹고 있어요（我正在吃）。","ko-g56-u01.g.x.1":"也能用来说最近一直在做的事：요즘 기타를 배우고 있어요。","ko-g56-u01.g.x.2":"过去就用 고 있었어요：그때 자고 있었어요（那时我正在睡觉）。","ko-g56-u01.g.0":"我正在吃。","ko-g56-u01.g.1":"宝宝在睡午觉。","ko-g56-u01.g.2":"哥哥在弹吉他。","ko-g56-u01.g.3":"你在做什么？","ko-g56-u01.g.4":"那时我正在看书。","ko-g56-u01.g.5":"妈妈在洗衣服。","ko-g56-u01.g.5.task":"说正在发生：用 -고 있어요。","ko-g56-u01.g.6":"我在给朋友发短信。","ko-g56-u01.g.6.task":"说正在发生：用 -고 있어요。","ko-g56-u01.g.7":"我最近在学游泳。","ko-g56-u01.g.7.task":"说最近在做：用 -고 있어요。","ko-g56-u02.title":"能和不能","ko-g56-u02.tip":"你现在正在读韩文——这是世宗大王为了让每个人都能读书而创造的文字。很酷吧！","ko-g56-u02.w.0":"韩文（韩语字母）","ko-g56-u02.w.1":"文字","ko-g56-u02.w.2":"声音","ko-g56-u02.w.3":"形状","ko-g56-u02.w.4":"国王","ko-g56-u02.w.5":"百姓（古词）","ko-g56-u02.w.6":"轻松地","ko-g56-u02.w.7":"开车","ko-g56-u02.w.8":"口哨","ko-g56-u02.w.9":"外语","ko-g56-u02.w.10":"创造了","ko-g56-u02.w.11":"聪明","ko-g56-u02.s.0":"弟弟（妹妹）能读一点韩文。","ko-g56-u02.s.1":"弟弟（妹妹）还不会骑自行车。","ko-g56-u02.s.2":"妈妈不会开车。","ko-g56-u02.s.3":"哥哥口哨吹得很好。","ko-g56-u02.s.4":"下雨了，所以不能在外面玩。","ko-g56-u02.s.5":"哥哥会说两种外语。","ko-g56-u02.s.6":"韩文很容易学会。","ko-g56-u02.s.7":"这些字很容易读。","ko-g56-u02.g.title":"能和不能：-(으)ㄹ 수 있어요 / 없어요","ko-g56-u02.g.x.0":"要说“能做”，就去掉 다 加上 ㄹ 수 있어요：가다 → 갈 수 있어요，하다 → 할 수 있어요。","ko-g56-u02.g.x.1":"有收音时加 을 수 있어요：읽다 → 읽을 수 있어요。以 ㄹ 结尾的词干不变：놀다 → 놀 수 있어요。","ko-g56-u02.g.x.2":"要说“不能”，就把 있어요 换成 없어요：갈 수 없어요。也可以在动词前加 못：못 가요。","ko-g56-u02.g.0":"我会读韩文。","ko-g56-u02.g.1":"爸爸会开车。","ko-g56-u02.g.2":"我今天不能玩。","ko-g56-u02.g.3":"你会吹口哨吗？","ko-g56-u02.g.4":"我不会游泳。","ko-g56-u02.g.5":"弟弟（妹妹）不会骑自行车。","ko-g56-u02.g.5.task":"改成“不能”：用 없어요。","ko-g56-u02.g.6":"哥哥会说外语。","ko-g56-u02.g.6.task":"说他能：用 -ㄹ 수 있어요。","ko-g56-u02.g.7":"你能读这些字吗？","ko-g56-u02.g.7.task":"问“你能吗”：用 -을 수 있어요。","ko-g56-u02.r.ko":"韩文的秘密","ko-g56-u02.r.genre":"历史","ko-g56-u02.r.p.0":"很久以前，韩国人用汉字写字。汉字数量非常多，又很难，所以很多普通百姓都不识字。","ko-g56-u02.r.p.1":"朝鲜的世宗大王很爱护百姓。于是在1443年，他创造了简单易学的文字。这种文字就是韩文。","ko-g56-u02.r.p.2":"辅音是看着发每个音时嘴巴和舌头的形状造出来的。例如 ㄱ 就是舌根挡住喉咙的样子。元音则是根据天、地、人造出来的。","ko-g56-u02.r.p.3":"韩文只用24个字母，就能写出几乎所有的声音。所以任何人几天就能学会读。每年10月9日“韩文日”，韩国人都会庆祝这种文字。","ko-g56-u02.r.q.3.o.0":"普通百姓","ko-g56-u02.r.q.3.o.1":"国王们","ko-g56-u02.r.q.3.o.2":"老师们","ko-g56-u03.title":"必须：-아야 해요","ko-g56-u03.tip":"韩国小朋友都会学这条交通安全规则：在斑马线前停下来，左右看看，举起手过马路。","ko-g56-u03.w.0":"规则","ko-g56-u03.w.1":"遵守（规则）","ko-g56-u03.w.2":"安全","ko-g56-u03.w.3":"头盔","ko-g56-u03.w.4":"过（马路）","ko-g56-u03.w.5":"红绿灯","ko-g56-u03.w.6":"斑马线","ko-g56-u03.w.7":"队伍","ko-g56-u03.w.8":"轮到、顺序","ko-g56-u03.w.9":"重要","ko-g56-u03.w.10":"干净地","ko-g56-u03.w.11":"一定","ko-g56-u03.s.0":"一定要把手洗干净。","ko-g56-u03.s.1":"一定要走斑马线过马路。","ko-g56-u03.s.2":"骑自行车时一定要戴头盔。","ko-g56-u03.s.3":"我们在食堂排队。","ko-g56-u03.s.4":"我明天得早点去学校。","ko-g56-u03.s.5":"我得先写作业。","ko-g56-u03.s.6":"大家都遵守规则。","ko-g56-u03.s.7":"绿灯亮了，一定要举手过马路。","ko-g56-u03.g.title":"必须：-아야 / -어야 해요","ko-g56-u03.g.x.0":"要说“必须做”，就用 요 形，去掉 요 再加 야 해요：가요 → 가야 해요，먹어요 → 먹어야 해요。","ko-g56-u03.g.x.1":"하다 动词变成 해야 해요：공부해야 해요（我必须学习）。","ko-g56-u03.g.x.2":"过去就说 해야 했어요：어제 일찍 자야 했어요（我昨天得早点睡）。","ko-g56-u03.g.0":"你必须洗手。","ko-g56-u03.g.1":"我现在得走了。","ko-g56-u03.g.2":"我得写作业。","ko-g56-u03.g.3":"你必须排队。","ko-g56-u03.g.4":"你必须戴头盔。","ko-g56-u03.g.5":"我明天得早起。","ko-g56-u03.g.5.task":"说必须：用 -아야 해요。","ko-g56-u03.g.6":"必须遵守学校的规则。","ko-g56-u03.g.6.task":"说必须：用 -어야 해요。","ko-g56-u03.g.7":"我昨天得学习。","ko-g56-u03.g.7.task":"改成昨天（过去时）。","ko-g56-u04.title":"如果、……的时候：-(으)면","ko-g56-u04.tip":"用你自己的一天造“如果”句：숙제를 다 하면 게임을 해요. 비가 오면 집에서 놀아요.","ko-g56-u04.w.0":"四季","ko-g56-u04.w.1":"分明","ko-g56-u04.w.2":"樱花","ko-g56-u04.w.3":"雨季","ko-g56-u04.w.4":"红叶","ko-g56-u04.w.5":"打雪仗","ko-g56-u04.w.6":"温暖","ko-g56-u04.w.7":"凉爽","ko-g56-u04.w.8":"如果","ko-g56-u04.w.9":"开（花）","ko-g56-u04.w.10":"落下","ko-g56-u04.w.11":"堆积","ko-g56-u04.s.0":"积雪了，我们就去滑雪橇。","ko-g56-u04.s.1":"天气暖和的话，我就去公园。","ko-g56-u04.s.2":"一到夏天，雨季就开始了。","ko-g56-u04.s.3":"渴了就喝水吧。","ko-g56-u04.s.4":"一到秋天，叶子就会落下。","ko-g56-u04.s.5":"没有时间的话，我们明天再做吧。","ko-g56-u04.s.6":"风凉爽的时候，我会去散步。","ko-g56-u04.s.7":"下雨的话，我们就在家玩。","ko-g56-u04.g.title":"如果、……的时候：-(으)면","ko-g56-u04.g.x.0":"去掉 다 加上 면，就表示“如果”或“……的时候”：오다 → 오면。비가 오면 우산을 써요（下雨的话，我就撑伞）。","ko-g56-u04.g.x.1":"有收音时加 으면：있다 → 있으면，먹다 → 먹으면。","ko-g56-u04.g.x.2":"以 ㄹ 结尾的词干直接加 면：놀다 → 놀면，만들다 → 만들면。","ko-g56-u04.g.0":"下雨的话，我就撑伞。","ko-g56-u04.g.1":"有时间的话，我们一起玩吧。","ko-g56-u04.g.2":"饿了就告诉我。","ko-g56-u04.g.3":"累了就休息吧。","ko-g56-u04.g.4":"吃了这个药就会好起来。","ko-g56-u04.g.5":"一到春天，樱花就开了。","ko-g56-u04.g.5.task":"用 -면（……的时候）连起来。","ko-g56-u04.g.6":"下雪的时候，我们就打雪仗。","ko-g56-u04.g.6.task":"用 -면（……的时候）连起来。","ko-g56-u04.g.7":"如果我会迟到，我就打电话。","ko-g56-u04.g.7.task":"用 -으면（如果）连起来。","ko-g56-u04.r.ko":"韩国的四季","ko-g56-u04.r.genre":"文化","ko-g56-u04.r.p.0":"韩国四季分明，春夏秋冬各不相同。春天一到，天气就变暖了。山上和街道上开满了樱花和迎春花。人们会去公园赏花。","ko-g56-u04.r.p.1":"夏天非常热。雨季一来，就会下很多雨。雨季结束后，孩子们就去海边或游泳池玩。","ko-g56-u04.r.p.2":"秋天风很凉爽。山上被红叶和黄叶装点得很美。冬天很冷。积雪以后，孩子们会堆雪人、打雪仗。","ko-g56-u04.r.q.3.o.0":"五颜六色的红叶","ko-g56-u04.r.q.3.o.1":"樱花","ko-g56-u04.r.q.3.o.2":"雪人","ko-g56-u05.title":"因为、所以：-아서","ko-g56-u05.tip":"만나서 반가워요（很高兴认识你）字面意思是“因为见到你，所以很高兴”——现在你能看到里面的 -아서 了！","ko-g56-u05.w.0":"睡懒觉","ko-g56-u05.w.1":"迟到（上学）","ko-g56-u05.w.2":"发烧","ko-g56-u05.w.3":"药","ko-g56-u05.w.4":"摔倒","ko-g56-u05.w.5":"受伤","ko-g56-u05.w.6":"滑","ko-g56-u05.w.7":"高兴（见到你）","ko-g56-u05.w.8":"晚了","ko-g56-u05.w.9":"错过（公交车）","ko-g56-u05.w.10":"所以","ko-g56-u05.w.11":"因为","ko-g56-u05.s.0":"我感冒了，所以没能去上学。","ko-g56-u05.s.1":"下雪了，所以路很滑。","ko-g56-u05.s.2":"我太困了，所以睡了个午觉。","ko-g56-u05.s.3":"我迟到了，所以坐了出租车。","ko-g56-u05.s.4":"再次见到朋友，我很高兴。","ko-g56-u05.s.5":"下雨了，所以我待在家里。","ko-g56-u05.s.6":"我去学校见到了朋友。","ko-g56-u05.s.7":"我受伤了，所以擦了药。","ko-g56-u05.g.title":"因为、所以：-아서 / -어서","ko-g56-u05.g.x.0":"要说理由，就用 요 形，去掉 요 加上 서：고파요 → 고파서。배가 고파서 먹었어요（我饿了，所以吃了东西）。","ko-g56-u05.g.x.1":"하다 动词变成 해서：피곤해서、공부해서。","ko-g56-u05.g.x.2":"只有最后一个动词表示过去：늦잠을 자서 늦었어요——绝不说 잤어서。","ko-g56-u05.g.x.3":"-아서/어서 也能按顺序连接动作：시장에 가서 과일을 샀어요（我去市场买了水果）。","ko-g56-u05.g.0":"我饿了，所以吃了面包。","ko-g56-u05.g.1":"我睡过头了，所以迟到了。","ko-g56-u05.g.2":"我发烧了，所以去了医院。","ko-g56-u05.g.3":"我太累了，所以早早就睡了。","ko-g56-u05.g.4":"很高兴认识你。","ko-g56-u05.g.5":"我没赶上公交车，所以迟到了。","ko-g56-u05.g.5.task":"用 -어서（所以）连起来。","ko-g56-u05.g.6":"路很滑，所以我摔倒了。","ko-g56-u05.g.6.task":"用 -어서（所以）连起来。","ko-g56-u05.g.7":"我去市场买了水果。","ko-g56-u05.g.7.task":"用 -아서 把步骤连起来。","ko-g56-u06.title":"但是：-지만","ko-g56-u06.tip":"过农历新年时，孩子们会向长辈磕头拜年，说 새해 복 많이 받으세요（新年多福）。","ko-g56-u06.w.0":"春节（农历新年）","ko-g56-u06.w.1":"传统节日","ko-g56-u06.w.2":"中秋节（秋夕）","ko-g56-u06.w.3":"拜年磕头","ko-g56-u06.w.4":"压岁钱","ko-g56-u06.w.5":"年糕汤","ko-g56-u06.w.6":"韩服","ko-g56-u06.w.7":"亲戚","ko-g56-u06.w.8":"聚在一起","ko-g56-u06.w.9":"收到","ko-g56-u06.w.10":"传统","ko-g56-u06.w.11":"但是","ko-g56-u06.s.0":"中秋节在秋天。","ko-g56-u06.s.1":"春节很忙，但是很开心。","ko-g56-u06.s.2":"外面很冷，但是家里很暖和。","ko-g56-u06.s.3":"弟弟（妹妹）个子小，但是力气很大。","ko-g56-u06.s.4":"我吃饱了。但是还想再吃。","ko-g56-u06.s.5":"春节时亲戚们会聚在一起。","ko-g56-u06.s.6":"我给爷爷磕头拜年了。","ko-g56-u06.s.7":"我收到了很多压岁钱。","ko-g56-u06.g.title":"但是：-지만 · 하지만","ko-g56-u06.g.x.0":"在一个句子里说“但是”，就去掉 다 加上 지만：맛있다 → 맛있지만。맛있지만 뜨거워요（好吃，但是很烫）。","ko-g56-u06.g.x.1":"-지만 对所有动词和形容词都一样：춥지만、예쁘지만、했지만。","ko-g56-u06.g.x.2":"用“但是”开始一个新句子时，用 하지만：피곤해요. 하지만 행복해요.","ko-g56-u06.g.0":"年糕汤很好吃，但是很烫。","ko-g56-u06.g.1":"天气很冷，但是我心情很好。","ko-g56-u06.g.2":"韩服很漂亮，但是有点不方便。","ko-g56-u06.g.3":"弟弟（妹妹）年纪小，但是很聪明。","ko-g56-u06.g.4":"我很累。但是我很幸福。","ko-g56-u06.g.5":"学习很难，但是很有趣。","ko-g56-u06.g.5.task":"用 -지만 合成一句话。","ko-g56-u06.g.6":"昨天下雨了，但是今天天晴了。","ko-g56-u06.g.6.task":"用 -지만 合成一句话。","ko-g56-u06.g.7":"哥哥个子高，但是我个子矮。","ko-g56-u06.g.7.task":"用 -지만 合成一句话。","ko-g56-u06.r.ko":"新年的早晨","ko-g56-u06.r.genre":"文化","ko-g56-u06.r.p.0":"今天是新年的早晨。智宇早早起床，穿上了韩服。韩服很漂亮，但是有点不方便。亲戚们都聚到了爷爷家。","ko-g56-u06.r.p.1":"智宇给爷爷奶奶磕头拜年。“新年快乐！”爷爷笑着给了她压岁钱。","ko-g56-u06.r.p.2":"早上大家一起喝年糕汤。在韩国，人们说喝了年糕汤就长大一岁。下午，智宇和堂兄弟姐妹们一起玩掷柶（一种韩国传统棋盘游戏）。她输了，但是玩得很开心。","ko-g56-u07.title":"更大、最大","ko-g56-u07.tip":"比较一下身边的东西：아빠가 엄마보다 커요. 고양이가 강아지보다 작아요. 你家里谁是 제일？","ko-g56-u07.w.0":"比","ko-g56-u07.w.1":"更","ko-g56-u07.w.2":"没那么","ko-g56-u07.w.3":"最","ko-g56-u07.w.4":"高","ko-g56-u07.w.5":"低","ko-g56-u07.w.6":"宽敞","ko-g56-u07.w.7":"窄","ko-g56-u07.w.8":"城市","ko-g56-u07.w.9":"乡下","ko-g56-u07.w.10":"堂表兄弟姐妹","ko-g56-u07.w.11":"比较","ko-g56-u07.s.0":"爸爸比妈妈高。","ko-g56-u07.s.1":"城市比乡下吵。","ko-g56-u07.s.2":"这个泡菜没有那个泡菜辣。","ko-g56-u07.s.3":"敏俊是我们班跑得最快的。","ko-g56-u07.s.4":"山比小山丘高。","ko-g56-u07.s.5":"在所有动物里，我最喜欢猫。","ko-g56-u07.s.6":"我的房间比弟弟（妹妹）的小。","ko-g56-u07.s.7":"我的表哥比我大一岁。","ko-g56-u07.g.title":"比较：보다 (더) · 제일 / 가장","ko-g56-u07.g.x.0":"比较时，在被比较的对象后面加 보다：형이 저보다 커요（哥哥比我高）。","ko-g56-u07.g.x.1":"也可以加上 더（更）或 덜（没那么）：서울이 부산보다 더 커요。","ko-g56-u07.g.x.2":"“最”用 제일 或 가장：제일 빨라요（最快）。说范围时加 에서：우리 반에서 제일 빨라요。","ko-g56-u07.g.0":"哥哥比我高。","ko-g56-u07.g.1":"首尔比釜山大。","ko-g56-u07.g.2":"今天没有昨天那么冷。","ko-g56-u07.g.3":"敏俊最快。","ko-g56-u07.g.4":"我最喜欢夏天。","ko-g56-u07.g.5":"乡下比城市安静。","ko-g56-u07.g.5.task":"和城市比较：加上 도시보다。","ko-g56-u07.g.6":"这条路比那条路宽。","ko-g56-u07.g.6.task":"和那条路比较：加上 저 길보다。","ko-g56-u07.g.7":"智宇是我们班最高的。","ko-g56-u07.g.7.task":"说“最高”：加上 제일。","ko-g56-u08.title":"善良的孩子、有趣的书","ko-g56-u08.tip":"介绍一下你喜欢的东西：제가 좋아하는 색, 제가 좋아하는 동물, 제가 좋아하는 음식은 …","ko-g56-u08.w.0":"新","ko-g56-u08.w.1":"旧","ko-g56-u08.w.2":"很久以前","ko-g56-u08.w.3":"善良","ko-g56-u08.w.4":"可爱","ko-g56-u08.w.5":"有名","ko-g56-u08.w.6":"安静","ko-g56-u08.w.7":"吵","ko-g56-u08.w.8":"亲切","ko-g56-u08.w.9":"无聊","ko-g56-u08.w.10":"一样","ko-g56-u08.w.11":"不同","ko-g56-u08.s.0":"奶奶有一只可爱的猫。","ko-g56-u08.s.1":"善良的孩子会帮助弟弟妹妹。","ko-g56-u08.s.2":"我在安静的图书馆看书。","ko-g56-u08.s.3":"这是一家有名的餐厅。","ko-g56-u08.s.4":"我喜欢善良的老师。","ko-g56-u08.s.5":"哥哥在看的动画片很有趣。","ko-g56-u08.s.6":"我最喜欢的颜色是绿色。","ko-g56-u08.s.7":"我穿上新鞋子。","ko-g56-u08.g.title":"修饰名词：-(으)ㄴ / -는","ko-g56-u08.g.x.0":"要把形容词放在名词前面，就去掉 다 加上 ㄴ：착하다 → 착한 아이（善良的孩子），크다 → 큰 집。","ko-g56-u08.g.x.1":"有收音时加 은：작다 → 작은 고양이。以 있다/없다 结尾的词加 는：재미있는 책。","ko-g56-u08.g.x.2":"正在进行的动作加 는：읽다 → 읽는 책（我在读的书），좋아하다 → 좋아하는 음식（喜欢的食物）。","ko-g56-u08.g.0":"是个善良的孩子。","ko-g56-u08.g.1":"有一只小猫。","ko-g56-u08.g.2":"我看有趣的书。","ko-g56-u08.g.3":"我最喜欢的食物是炒年糕。","ko-g56-u08.g.4":"我在安静的图书馆学习。","ko-g56-u08.g.5":"我有一只可爱的小狗。","ko-g56-u08.g.5.task":"用一句话，把“可爱”放在 강아지 前面。","ko-g56-u08.g.6":"这是一首有名的歌。","ko-g56-u08.g.6.task":"说“有名的歌”：把 유명한 放在 노래 前面。","ko-g56-u08.g.7":"我现在在读的书很有趣。","ko-g56-u08.g.7.task":"合成一句话：읽는 책。","ko-g56-u09.title":"尊敬长辈","ko-g56-u09.tip":"韩国的爷爷奶奶常常亲昵地叫孙子孙女 우리 강아지（我的小狗狗）。这是个很甜的昵称！","ko-g56-u09.w.0":"府上（长辈的家）","ko-g56-u09.w.1":"用餐（长辈的饭）","ko-g56-u09.w.2":"请用餐（对长辈说）","ko-g56-u09.w.3":"就寝（长辈睡觉）","ko-g56-u09.w.4":"在（长辈在）","ko-g56-u09.w.5":"给（长辈）","ko-g56-u09.w.6":"呈给（长辈）","ko-g56-u09.w.7":"贵庚（长辈的年龄）","ko-g56-u09.w.8":"话（长辈的话）","ko-g56-u09.w.9":"敬语","ko-g56-u09.w.10":"大人","ko-g56-u09.w.11":"孙子孙女","ko-g56-u09.s.0":"爷爷，请用。","ko-g56-u09.s.1":"老师在教室里。","ko-g56-u09.s.2":"爷爷现在正在睡觉。","ko-g56-u09.s.3":"我送了花给奶奶。","ko-g56-u09.s.4":"爷爷正在看报纸。","ko-g56-u09.s.5":"我认真听老师的话。","ko-g56-u09.s.6":"我们对大人要用敬语。","ko-g56-u09.s.7":"你爷爷多大年纪了？","ko-g56-u09.g.title":"表示尊敬：-(으)세요 · 께 · 特别的词","ko-g56-u09.g.x.0":"说到长辈时，在动词里加 시：가요 → 가세요，웃어요 → 웃으세요（奶奶在笑）。","ko-g56-u09.g.x.1":"有些词会完全变样：먹어요 → 드세요，자요 → 주무세요，있어요 → 계세요，집 → 댁，나이 → 연세。","ko-g56-u09.g.x.2":"对长辈说“给”用 께（할머니께 드려요），用 께서 代替 이/가（할머니께서 웃으세요）。","ko-g56-u09.g.0":"奶奶，请吃饭。","ko-g56-u09.g.1":"爷爷在他的房间里。","ko-g56-u09.g.2":"奶奶，晚安。","ko-g56-u09.g.3":"我给老师写了一封信。","ko-g56-u09.g.4":"奶奶在笑。","ko-g56-u09.g.5":"我去爷爷家。","ko-g56-u09.g.5.task":"用长辈的家的尊敬说法：댁。","ko-g56-u09.g.6":"你奶奶多大年纪了？","ko-g56-u09.g.6.task":"用长辈年龄的尊敬说法：연세。","ko-g56-u09.g.7":"我送爸爸礼物。","ko-g56-u09.g.7.task":"用送给长辈的尊敬动词：드려요。","ko-g56-u09.r.ko":"在奶奶家","ko-g56-u09.r.genre":"故事","ko-g56-u09.r.p.0":"星期六，河俊去了乡下的奶奶家。奶奶在门口等着他。“奶奶好！”河俊大声地打招呼。","ko-g56-u09.r.p.1":"傍晚，奶奶做了好吃的大酱汤。河俊把勺子递给奶奶。“奶奶，请吃饭。”奶奶笑着说：“我的孙子最棒了！”","ko-g56-u09.r.p.2":"晚上，奶奶给他讲了一个古老的故事。河俊听着听着就睡着了。奶奶给他盖上被子。“好好睡吧，我的小狗狗。”","ko-g56-u09.r.q.2.o.0":"孙子","ko-g56-u09.r.q.2.o.1":"奶奶","ko-g56-u09.r.q.2.o.2":"邻居","ko-g56-u10.title":"试试看","ko-g56-u10.tip":"问问家人有没有这些经历：한국 음식을 먹어 봤어요? 태권도를 해 봤어요?","ko-g56-u10.w.0":"经历","ko-g56-u10.w.1":"第一次","ko-g56-u10.w.2":"一次","ko-g56-u10.w.3":"味道","ko-g56-u10.w.4":"气味","ko-g56-u10.w.5":"神奇","ko-g56-u10.w.6":"拌饭","ko-g56-u10.w.7":"跆拳道","ko-g56-u10.w.8":"韩屋（韩国传统房子）","ko-g56-u10.w.9":"穿（鞋、袜子）","ko-g56-u10.w.10":"怎么样？","ko-g56-u10.w.11":"游乐设施","ko-g56-u10.s.0":"也尝尝这个泡菜吧。","ko-g56-u10.s.1":"你吃过炒年糕吗？","ko-g56-u10.s.2":"嗯，我吃过一次。","ko-g56-u10.s.3":"戴戴这顶帽子试试。","ko-g56-u10.s.4":"我想试着学跆拳道。","ko-g56-u10.s.5":"我第一次在韩屋里睡觉。","ko-g56-u10.s.6":"味道怎么样？","ko-g56-u10.s.7":"这真是一次很神奇的经历。","ko-g56-u10.g.title":"试试：-아/어 보세요 · -아/어 봤어요","ko-g56-u10.g.x.0":"在 -아/어 形后面加 보세요，就是“试试看”：먹어 보세요（尝尝看），입어 보세요（穿穿看）。","ko-g56-u10.g.x.1":"봤어요 表示以前试过：먹어 봤어요（我吃过）。","ko-g56-u10.g.x.2":"用 봤어요? 问别人的经历：한국에 가 봤어요? ——你去过韩国吗？","ko-g56-u10.g.0":"尝尝这个年糕吧。","ko-g56-u10.g.1":"穿穿这件衣服吧。","ko-g56-u10.g.2":"你吃过拌饭吗？","ko-g56-u10.g.3":"我去过韩国。","ko-g56-u10.g.4":"去学学跆拳道吧。","ko-g56-u10.g.5":"我在韩屋里住过。","ko-g56-u10.g.5.task":"说你有过这个经历：用 -아 봤어요。","ko-g56-u10.g.6":"穿穿这双鞋吧。","ko-g56-u10.g.6.task":"邀请对方试试：用 -어 보세요。","ko-g56-u10.g.7":"你坐过那个游乐设施吗？","ko-g56-u10.g.7.task":"问问经历：用 -아 봤어요?。","ko-g56-u11.title":"我们……好吗？","ko-g56-u11.tip":"在韩国，几乎在哪里都能叫外卖——就连河边的公园也行！","ko-g56-u11.w.0":"郊游","ko-g56-u11.w.1":"便当","ko-g56-u11.w.2":"野餐垫","ko-g56-u11.w.3":"炸鸡","ko-g56-u11.w.4":"外卖","ko-g56-u11.w.5":"汉江","ko-g56-u11.w.6":"放（风筝）","ko-g56-u11.w.7":"借、租","ko-g56-u11.w.8":"点（餐）","ko-g56-u11.w.9":"一起","ko-g56-u11.w.10":"风景","ko-g56-u11.w.11":"晚霞","ko-g56-u11.s.0":"我们明天去公园好吗？","ko-g56-u11.s.1":"我们几点见？","ko-g56-u11.s.2":"我们点披萨好吗？","ko-g56-u11.s.3":"我们一起放风筝好吗？","ko-g56-u11.s.4":"我们把垫子铺在这里好吗？","ko-g56-u11.s.5":"我们在汉江边放风筝。","ko-g56-u11.s.6":"晚霞真美。","ko-g56-u11.s.7":"我们今天吃什么呢？","ko-g56-u11.g.title":"我们……好吗？：-(으)ㄹ까요?","ko-g56-u11.g.x.0":"提议一起做某事时，去掉 다 加上 ㄹ까요?：가다 → 갈까요?（我们去好吗？）","ko-g56-u11.g.x.1":"有收音时加 을까요?：먹다 → 먹을까요?，앉다 → 앉을까요?","ko-g56-u11.g.x.2":"可以回答 네, 좋아요!，或者用 요 形提别的建议：공원에 가요!（我们去公园吧！）","ko-g56-u11.g.0":"这个周末我们去郊游好吗？","ko-g56-u11.g.1":"我们吃什么呢？","ko-g56-u11.g.2":"我们在哪里见面？","ko-g56-u11.g.3":"我们一起骑自行车好吗？","ko-g56-u11.g.4":"我们坐这里好吗？","ko-g56-u11.g.5":"我们点炸鸡好吗？","ko-g56-u11.g.5.task":"改成提议：用 -을까요?。","ko-g56-u11.g.6":"我们去汉江放风筝好吗？","ko-g56-u11.g.6.task":"改成提议：用 -ㄹ까요?。","ko-g56-u11.g.7":"今天我们一起去图书馆好吗？","ko-g56-u11.g.7.task":"改成提议：用 -ㄹ까요?。","ko-g56-u11.r.ko":"汉江野餐","ko-g56-u11.r.genre":"日记","ko-g56-u11.r.p.0":"10月3日，星期天，天气晴。我们一家人去汉江野餐。妈妈给我们做了紫菜包饭便当。","ko-g56-u11.r.p.1":"爸爸问：“我们租自行车骑好吗？”我们沿着河边骑车。风很凉爽，我的心情好极了。","ko-g56-u11.r.p.2":"中午我们铺开垫子吃便当。弟弟（妹妹）说也想吃炸鸡，所以我们叫了炸鸡外卖。连汉江边都能送外卖，真是太神奇了。","ko-g56-u11.r.p.3":"傍晚我们放风筝、看晚霞。天空被染得红红的，非常美丽。我下个周末还想再来。","ko-g56-u11.r.q.3.o.0":"晚霞中的红色天空","ko-g56-u11.r.q.3.o.1":"风筝","ko-g56-u11.r.q.3.o.2":"野餐垫","ko-g56-u12.title":"请不要……","ko-g56-u12.tip":"在韩国的告示牌上常看到 -지 마세요：만지지 마세요（请勿触摸），들어가지 마세요（请勿进入）。","ko-g56-u12.w.0":"吵闹","ko-g56-u12.w.1":"摸","ko-g56-u12.w.2":"扔掉","ko-g56-u12.w.3":"垃圾","ko-g56-u12.w.4":"危险","ko-g56-u12.w.5":"担心","ko-g56-u12.w.6":"恶作剧","ko-g56-u12.w.7":"美术馆","ko-g56-u12.w.8":"作品","ko-g56-u12.w.9":"拍照、摄影","ko-g56-u12.w.10":"食物（和饮料）","ko-g56-u12.w.11":"急","ko-g56-u12.s.0":"在图书馆里不要吵闹。","ko-g56-u12.s.1":"请不要摸画。","ko-g56-u12.s.2":"不要在街上乱扔垃圾。","ko-g56-u12.s.3":"别太担心。","ko-g56-u12.s.4":"不要在马路上跑，很危险。","ko-g56-u12.s.5":"走楼梯不要急。","ko-g56-u12.s.6":"在美术馆里不要拍照。","ko-g56-u12.s.7":"不要对朋友恶作剧。","ko-g56-u12.g.title":"请不要：-지 마세요","ko-g56-u12.g.x.0":"礼貌地叫别人不要做某事，就去掉 다 加上 지 마세요：만지다 → 만지지 마세요（请不要摸）。","ko-g56-u12.g.x.1":"每个动词都一样：먹지 마세요、뛰지 마세요、걱정하지 마세요。","ko-g56-u12.g.x.2":"对好朋友可以说 -지 마：울지 마!（别哭！）","ko-g56-u12.g.0":"请不要触摸作品。","ko-g56-u12.g.1":"别担心。","ko-g56-u12.g.2":"不要在教室里吵闹。","ko-g56-u12.g.3":"不要在马路上跑。","ko-g56-u12.g.4":"请不要在这里吃东西。","ko-g56-u12.g.5":"不要乱扔垃圾。","ko-g56-u12.g.5.task":"改成“不要”：用 -지 마세요。","ko-g56-u12.g.6":"在美术馆里请不要拍照。","ko-g56-u12.g.6.task":"改成“不要”：用 -지 마세요。","ko-g56-u12.g.7":"不要着急。","ko-g56-u12.g.7.task":"改成“不要”：用 -지 마세요。","ko-g56-u13.title":"之前和之后","ko-g56-u13.tip":"和家人一起做紫菜包饭（或者别的简单食物），用韩语说出每一步：먼저 …, 그다음에 …, 마지막으로 …","ko-g56-u13.w.0":"材料","ko-g56-u13.w.1":"紫菜","ko-g56-u13.w.2":"铺开","ko-g56-u13.w.3":"卷起来","ko-g56-u13.w.4":"切片","ko-g56-u13.w.5":"刀","ko-g56-u13.w.6":"搅拌","ko-g56-u13.w.7":"香油","ko-g56-u13.w.8":"火腿","ko-g56-u13.w.9":"腌黄萝卜","ko-g56-u13.w.10":"最后","ko-g56-u13.w.11":"小心","ko-g56-u13.s.0":"睡觉前我会看书。","ko-g56-u13.s.1":"打扫完我吃点心。","ko-g56-u13.s.2":"去学校前我吃早饭。","ko-g56-u13.s.3":"游泳后我洗澡。","ko-g56-u13.s.4":"做饭前我先洗材料。","ko-g56-u13.s.5":"把米饭铺在紫菜上。","ko-g56-u13.s.6":"用刀的时候要小心。","ko-g56-u13.s.7":"最后把紫菜包饭切开。","ko-g56-u13.g.title":"之前和之后：-기 전에 · -(으)ㄴ 후에","ko-g56-u13.g.x.0":"“做……之前”：去掉 다 加上 기 전에：먹다 → 먹기 전에（吃之前）。","ko-g56-u13.g.x.1":"“做……之后”：去掉 다 加上 ㄴ 후에：하다 → 한 후에。有收音时加 은 후에：먹다 → 먹은 후에。","ko-g56-u13.g.x.2":"名词后面直接加 전에 或 후에：수업 전에，방학 후에。","ko-g56-u13.g.0":"吃饭前我洗手。","ko-g56-u13.g.1":"写完作业后我去玩。","ko-g56-u13.g.2":"睡觉前我刷牙。","ko-g56-u13.g.3":"吃完饭后我去散步。","ko-g56-u13.g.4":"放学后我去学跆拳道。","ko-g56-u13.g.5":"做紫菜包饭前，我们先准备材料。","ko-g56-u13.g.5.task":"用 -기 전에 合成一句话。","ko-g56-u13.g.6":"看完电影后我们去吃饭。","ko-g56-u13.g.6.task":"用 -ㄴ 후에 合成一句话。","ko-g56-u13.g.7":"洗完澡后我换上睡衣。","ko-g56-u13.g.7.task":"用 -ㄴ 후에 合成一句话。","ko-g56-u13.r.ko":"一起做紫菜包饭","ko-g56-u13.r.genre":"食谱","ko-g56-u13.r.p.0":"紫菜包饭是韩国人去郊游时常吃的食物。今天我要和妈妈一起做紫菜包饭。开始之前，我先把手洗干净。","ko-g56-u13.r.p.1":"首先，准备好材料。需要紫菜、米饭、鸡蛋、火腿、腌黄萝卜和菠菜。在米饭里加盐和香油拌匀。妈妈用刀把火腿和鸡蛋切成长条。刀很危险，所以要由大人来用。","ko-g56-u13.r.p.2":"把米饭薄薄地铺在紫菜上。放上馅料以后，紧紧地卷起来。最后，妈妈帮我把紫菜包饭切开。我亲手做的紫菜包饭真好吃！","ko-g56-u14.title":"和朋友聊天","ko-g56-u14.tip":"在韩国，只有关系好、年龄差不多的人之间才能用 반말（平语）。不确定的话就保留 요——这样永远不会错！","ko-g56-u14.w.0":"平语（非敬语）","ko-g56-u14.w.1":"关系亲近","ko-g56-u14.w.2":"嗯（随意的“是”）","ko-g56-u14.w.3":"不（随意的“不是”）","ko-g56-u14.w.4":"谢啦（随意说法）","ko-g56-u14.w.5":"抱歉啦（随意说法）","ko-g56-u14.w.6":"没事啦（随意说法）","ko-g56-u14.w.7":"你在干嘛？（随意说法）","ko-g56-u14.w.8":"一起玩吧","ko-g56-u14.w.9":"真的（随意说法）","ko-g56-u14.w.10":"关系","ko-g56-u14.w.11":"同岁","ko-g56-u14.s.0":"我们同岁吗？","ko-g56-u14.s.1":"嗯，我也十岁。","ko-g56-u14.s.2":"你今天要干嘛？","ko-g56-u14.s.3":"去我家吧！","ko-g56-u14.s.4":"刚才的事对不起啦。","ko-g56-u14.s.5":"没事，别在意。","ko-g56-u14.s.6":"这首歌真好听！","ko-g56-u14.s.7":"我们对老师用敬语。","ko-g56-u14.g.title":"和朋友说平语：去掉 요","ko-g56-u14.g.x.0":"对好朋友和比自己小的孩子，韩国人会用 반말（平语）。大多数时候只要去掉 요：가요 → 가，먹어요 → 먹어。","ko-g56-u14.g.x.1":"이에요/예요 变成 이야/야：학생이에요 → 학생이야，친구예요 → 친구야。","ko-g56-u14.g.x.2":"对朋友说“……吧”用 -자：가자! 먹자! 놀자! 还有 네 → 응，아니요 → 아니。","ko-g56-u14.g.x.3":"对大人、老师和刚认识的人，一定要用 요！","ko-g56-u14.g.0":"你现在在干嘛？","ko-g56-u14.g.1":"我也十岁。","ko-g56-u14.g.2":"这是我的朋友。","ko-g56-u14.g.3":"一起吃吧！","ko-g56-u14.g.4":"对不起，我迟到了。","ko-g56-u14.g.5":"一起玩吧！","ko-g56-u14.g.5.task":"对好朋友说：用 -자。","ko-g56-u14.g.6":"这个游戏真好玩！","ko-g56-u14.g.6.task":"对好朋友说：去掉 요，用 진짜。","ko-g56-u14.g.7":"我是学生。","ko-g56-u14.g.7.task":"用 반말 说：저는 → 나는，이에요 → 이야。","ko-g56-u15.title":"……的时候：-(으)ㄹ 때","ko-g56-u15.tip":"用 -ㄹ 때 聊聊心情：기쁠 때 노래해요. 슬플 때 엄마를 안아요. 你无聊的时候会做什么？","ko-g56-u15.w.0":"困","ko-g56-u15.w.1":"渴","ko-g56-u15.w.2":"好奇","ko-g56-u15.w.3":"委屈、不高兴","ko-g56-u15.w.4":"孤单","ko-g56-u15.w.5":"辛苦","ko-g56-u15.w.6":"安慰","ko-g56-u15.w.7":"一个人","ko-g56-u15.w.8":"想法","ko-g56-u15.w.9":"回忆","ko-g56-u15.w.10":"小时候","ko-g56-u15.w.11":"KTV","ko-g56-u15.s.0":"无聊的时候我会画画。","ko-g56-u15.s.1":"饿的时候我会吃苹果。","ko-g56-u15.s.2":"好奇的时候我会问老师。","ko-g56-u15.s.3":"朋友不高兴的时候，我会安慰他。","ko-g56-u15.s.4":"一个人的时候我会看书。","ko-g56-u15.s.5":"我小时候住在乡下。","ko-g56-u15.s.6":"难过的时候我会想起朋友。","ko-g56-u15.s.7":"去 KTV 的时候我会很兴奋。","ko-g56-u15.g.title":"……的时候：-(으)ㄹ 때","ko-g56-u15.g.x.0":"要说“……的时候”，就去掉 다 加上 ㄹ 때：졸리다 → 졸릴 때（困的时候）。","ko-g56-u15.g.x.1":"有收音时加 을 때：먹다 → 먹을 때，있다 → 있을 때。","ko-g56-u15.g.x.2":"过去用 았/었을 때：어렸을 때（小时候）。名词直接加 때：방학 때，점심 때。","ko-g56-u15.g.0":"困的时候我去洗脸。","ko-g56-u15.g.1":"吃东西的时候不要说话。","ko-g56-u15.g.2":"一个人的时候我会听音乐。","ko-g56-u15.g.3":"好奇的时候就问吧。","ko-g56-u15.g.4":"放假的时候我去奶奶家。","ko-g56-u15.g.5":"渴的时候我喝水。","ko-g56-u15.g.5.task":"用 -ㄹ 때 合成一句话。","ko-g56-u15.g.6":"我不高兴的时候，妈妈会安慰我。","ko-g56-u15.g.6.task":"用 -ㄹ 때 合成一句话。","ko-g56-u15.g.7":"我小时候住在乡下。","ko-g56-u15.g.7.task":"用 -았/었을 때 合成一句话。","ko-g56-u16.title":"讲故事","ko-g56-u16.tip":"《兴夫和孬夫》是韩国最有名的民间故事之一。用 먼저、그다음에、그런데、마지막으로 讲给家人听吧！","ko-g56-u16.w.0":"首先","ko-g56-u16.w.1":"然后","ko-g56-u16.w.2":"可是","ko-g56-u16.w.3":"突然","ko-g56-u16.w.4":"最后","ko-g56-u16.w.5":"贪心","ko-g56-u16.w.6":"贫穷","ko-g56-u16.w.7":"有钱人","ko-g56-u16.w.8":"燕子","ko-g56-u16.w.9":"种子","ko-g56-u16.w.10":"葫芦","ko-g56-u16.w.11":"宝物","ko-g56-u16.s.0":"首先，我写作业。","ko-g56-u16.s.1":"然后，我和小狗玩。","ko-g56-u16.s.2":"最后，我写日记。","ko-g56-u16.s.3":"我们去郊游了。可是，我们忘了带便当。","ko-g56-u16.s.4":"突然，一只小狗跑了过来。","ko-g56-u16.s.5":"我肚子疼，所以要去医院。","ko-g56-u16.s.6":"孬夫非常贪心。","ko-g56-u16.s.7":"葫芦里冒出了宝物。","ko-g56-u16.g.title":"按顺序讲：먼저, 그다음에, 그래서, 그런데","ko-g56-u16.g.x.0":"在句子开头用这些词，按顺序讲事情：먼저（首先）→ 그다음에（然后）→ 마지막으로（最后）。","ko-g56-u16.g.x.1":"그래서 表示“所以”（结果）：비가 와요. 그래서 집에 있어요.","ko-g56-u16.g.x.2":"그런데 表示“可是”或“结果”（意想不到的事）：공원에 갔어요. 그런데 문이 닫혀 있었어요.","ko-g56-u16.g.x.3":"갑자기 表示“突然”：갑자기 불이 꺼졌어요.","ko-g56-u16.g.0":"首先，洗手。","ko-g56-u16.g.1":"然后，吃饭。","ko-g56-u16.g.2":"在下雨。所以我撑伞。","ko-g56-u16.g.3":"我去了公园。可是下起雨来了。","ko-g56-u16.g.4":"最后，刷牙。","ko-g56-u16.g.5":"我饿了。所以吃了面包。","ko-g56-u16.g.5.task":"用 그래서 分成两句话。","ko-g56-u16.g.6":"我正在走路。突然下雨了。","ko-g56-u16.g.6.task":"加上“突然”：用 갑자기。","ko-g56-u16.g.7":"我先写作业，然后再玩。","ko-g56-u16.g.7.task":"分两步说：먼저 … 그다음에 …","ko-g56-u16.r.ko":"兴夫和孬夫","ko-g56-u16.r.genre":"民间故事","ko-g56-u16.r.p.0":"很久很久以前，有一对兄弟，叫兴夫和孬夫。哥哥孬夫很有钱，却非常贪心。弟弟兴夫很穷，但心地善良。","ko-g56-u16.r.p.1":"一个春天，兴夫看见一只腿受伤的燕子。他小心翼翼地把燕子的腿治好了。秋天到了，燕子飞到了温暖的南方。","ko-g56-u16.r.p.2":"第二年春天，燕子衔着一颗葫芦种子飞了回来。兴夫把种子种下，长出了巨大的葫芦。他把葫芦剖开，金子和宝物源源不断地涌了出来！","ko-g56-u16.r.p.3":"孬夫听说了这件事，就故意弄伤了一只燕子的腿。可是，孬夫的葫芦里跑出了鬼怪，把他狠狠地教训了一顿。最后，孬夫为自己做的事感到后悔，变成了一个好人。","ko-g56-u16.r.q.3.o.0":"贪心","ko-g56-u16.r.q.3.o.1":"善良","ko-g56-u16.r.q.3.o.2":"宝物"},w={"tier.first.label":"第一批单词","tier.first.age":"还不识字也可以","tier.first.desc":"听单词、点图片 · 不识字也没关系","tier.kinder.label":"韩文字母","tier.kinder.age":"初学从这里开始","tier.kinder.desc":"韩文字母和拼读 · 问候、数字、颜色","tier.g12.label":"第一个句子","tier.g12.age":"会读韩文字母后","tier.g12.desc":"食物、身体、学校、天气单词 · 短句","tier.g34.label":"基础语法","tier.g34.age":"会说短句后","tier.g34.desc":"助词、动词词尾、过去和将来 · 对话","tier.g56.label":"阅读","tier.g56.age":"会造句后","tier.g56.desc":"能、必须、敬语 · 短文阅读"},t={...w,...g,...k,...o,...u,...s};export{t as default};
